insert into public.sources (title, url, kind, publisher, published_on) values ('Decret 276/2016, de 19 de juliol, de les funcions de guàrdia i del sistema de comandament dels serveis de prevenció, extinció d''incendis i salvaments de la Generalitat de Catalunya', 'https://portaljuridic.gencat.cat/eli/es-ct/d/2016/07/19/276', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Portal Jurídic de Catalunya', null) on conflict (url) do nothing;
