insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Funció dels vehicles en les emergències i classificació"},{"n":"2","title":"Mitjans terrestres, aeris i aquàtics"},{"n":"3","title":"Autobombes: BUL, BUP, BRP i BNP"},{"n":"4","title":"Vehicles especials: autoescales (AEA)"},{"n":"5","title":"Grua pesada i grua lleugera; seguretat amb AEA"},{"n":"6","title":"Furgons de salvament i vehicles de riscos tecnològics"},{"n":"7","title":"Vehicles de comandament, sanitaris i de suport"}]'::jsonb, '["§ finalitat de cada vehicle MAN.EQIP.000: «Cada vehicle està dissenyat i equipat amb una finalitat específica, la qual determina la seva estructura, el material transportat i el tipus d’intervencions on és més efectiu.»","§ vehicles d''extinció MAN.EQIP.000: «Autobombes i vehicles d’extinció Els vehicles d’extinció són el pilar fonamental del parc mòbil dels serveis de bombers.»","§ BUP MAN.EQIP.000: «Capacitat d’aigua: entre 3.000 i 4.000 litres.»","§ estabilitat AEA MAN.EQIP.000: «Per garantir l’estabilitat, cal emplaçar l’autoescala en un terreny ferm, estable i planer, utilitzant correctament els estabilitzadors i evitant sobrecàrregues.»","§ comunicació AEA MAN.EQIP.000: «La comunicació clara i coordinada entre l’operador de l’escala, el conductor i el comandament és fonamental durant totes les maniobres.»","§ FSV MAN.EQIP.000: «Són vehicles essencials en serveis de rescat tècnic, i sovint actuen en coordinació amb les autobombes.»","§ vehicles de comandament MAN.EQIP.000: «És des d’aquests vehicles, on es coordinen els recursos operatius, es prenen decisions tàctiques i es manté la comunicació amb els centres o sales de coordinació.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Funció operativa dels vehicles i classificació","blocks":[{"text":"Cada vehicle d''emergència està dissenyat i equipat amb una finalitat específica, que en determina l''estructura, el material que transporta i el tipus d''intervencions en què és més efectiu. La classificació general i la codificació específica dels vehicles del Cos, com a llistat complet, no són als extractes revisats; cal consultar el manual MAN.EQIP.000.","refs":[{"ref":"MAN.EQIP.000","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"Cada vehicle està dissenyat i equipat amb una finalitat específica, la qual determina la seva estructura, el material transportat i el tipus d’intervencions on és més efectiu."}]}]},{"n":"2","title":"Tipus de mitjans: terrestres, aeris i aquàtics","blocks":[{"text":"Els mitjans terrestres són els més utilitzats en la majoria d''emergències, especialment a escala municipal, comarcal o regional. Els mitjans aeris (helicòpters i avions) són un recurs molt especialitzat i d''alt cost, però essencial en determinades situacions: zones de difícil accés, incendis forestals d''alta intensitat o rescats complexos de muntanya o marítims. Els mitjans aquàtics no són als extractes revisats; cal consultar el manual MAN.EQIP.000.","refs":[{"ref":"MAN.EQIP.000","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"Mitjans terrestres: definició, característiques i funcions Els mitjans terrestres són els més utilitzats en la majoria d’emergències, especialment a escala municipal, comarcal o regional."},{"ref":"MAN.EQIP.000","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"Mitjans aeris: helicòpters i avions, usos i protocols Els mitjans aeris són un recurs altament especialitzat i d’alt cost, però essencial en determinades situacions, especialment en zones de difícil accés, en incendis forestals d’alta intensitat o en rescats complexos de muntanya o marítims."}]}]},{"n":"3","title":"Autobombes: definició i característiques comunes","blocks":[{"text":"Els vehicles d''extinció són el pilar fonamental del parc mòbil dels serveis de bombers. Una autobomba és un vehicle especialitzat equipat amb una cisterna d''aigua, una bomba d''impulsió i un conjunt de mànegues, eines i equips complementaris per a l''extinció d''incendis i altres actuacions de salvament.","refs":[{"ref":"MAN.EQIP.000","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"Autobombes i vehicles d’extinció Els vehicles d’extinció són el pilar fonamental del parc mòbil dels serveis de bombers."},{"ref":"MAN.EQIP.000","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"Definició i característiques de les autobombes Una autobomba és un vehicle especialitzat equipat amb una cisterna d’aigua, una bomba d’impulsió i una sèrie de mànegues, eines i equips complementaris per permetre l’extinció d’incendis i altres actuacions de salvament."}]},{"text":"Totes les autobombes del Cos de Bombers de la Generalitat porten bombes centrífugues d''alta i baixa pressió, de manera que poden tirar aigua amb tots els diàmetres de mànega de què es disposa.","refs":[{"ref":"MAN.EQIP.000","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"Totes les autobombes del Cos de Bombers de la Generalitat estan equipades amb bombes centrífugues d’alta i baixa pressió per poder tirar aigua amb tots els diàmetres de mànegues dels quals es disposa."}]}]},{"n":"4","title":"Tipus principals d''autobombes","blocks":[{"text":"La Bomba Urbana Lleugera (BUL) té una capacitat d''aigua d''entre 1.000 i 1.650 litres. La Bomba Urbana Pesada (BUP) en porta entre 3.000 i 4.000 litres, però és menys maniobrable en entorns molt estrets o d''accés difícil.","refs":[{"ref":"MAN.EQIP.000 (BUL)","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"Capacitat d’aigua: entre 1.000 i 1.650 litres."},{"ref":"MAN.EQIP.000 (BUP)","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"Capacitat d’aigua: entre 3.000 i 4.000 litres."},{"ref":"MAN.EQIP.000 (BUP)","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"Menys maniobrable en entorns molt estres o d’accés difícil"}]},{"text":"La Bomba Rural Pesada (BRP) és l''autobomba estàndard de la majoria de parcs de Bombers de la Generalitat. Porta bomba d''alta i baixa pressió i mànegues variades, però especialment de 25 mm.","refs":[{"ref":"MAN.EQIP.000 (BRP)","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"És l’autobomba estàndard de la majoria de parcs de Bombers de la Generalitat de Catalunya."},{"ref":"MAN.EQIP.000 (BRP)","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"Bomba d’alta i baixa pressió, i mànegues variades, però especialment de 25 mm."}]},{"text":"La Bomba Nodrissa Pesada (BNP) té una capacitat d''aigua d''entre 7.000 i 10.000 litres i una bomba d''alta capacitat de fins a 5.000 l/min a 10 bars. És essencial en serveis que necessiten grans cabals o en zones sense hidrants.","refs":[{"ref":"MAN.EQIP.000 (BNP)","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"Capacitat d’aigua: entre 7.000 i 10.000 litres."},{"ref":"MAN.EQIP.000 (BNP)","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"Bomba alta capacitat fins a 5000 l/min de cabal a 10 bars."},{"ref":"MAN.EQIP.000 (BNP)","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"És essencial en serveis amb necessitat de grans cabals o en zones sense hidrants."}]}]},{"n":"5","title":"Autoescales (AEA): funció i característiques","blocks":[{"text":"Les autoescales (AEA) són vehicles dissenyats per treballar en alçada i fer salvaments verticals, suport i rescat amb accés per façana i transport d''eines. Les autoescales sense braç articulat tenen una alçada útil d''entre 20 i 42 metres.","refs":[{"ref":"MAN.EQIP.000","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"Les autoescales (AEA) són vehicles dissenyats per treballar en alçada i fer salvaments verticals, suport i rescat d’accés per façana i transport d’eines."},{"ref":"MAN.EQIP.000 (AEA sense braç articulat)","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"Alçada útil entre 20 i 42 metres"}]},{"text":"Totes les autoescales modernes poden fer de grua amb càrregues pesades fent servir el primer tram d''escala, amb els altres trams totalment recollits; però només es fa en casos d''emergència, perquè l''autoescala no és un vehicle dissenyat per moure càrregues. Hi ha també la grua lleugera, que, a diferència de la pesada, es fa amb tot el braç d''escala i la càrrega subjectada a l''extrem de l''últim tram.","refs":[{"ref":"MAN.EQIP.000","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"Totes les autoescales modernes poden fer de grua amb càrregues pesades fent servir el primer tram d''escala (i els altres trams totalment recollits), però només es fa servir en casos d’emergència ja que l’autoescala no és un vehicle dissenyat per moure càrregues."},{"ref":"MAN.EQIP.000","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"També hi ha el que s''anomena la grua lleugera, que a diferència de la pesada, es fa amb tot el braç d''escala subjectant la càrrega a l''extrem de l''últim tram."}]}]},{"n":"6","title":"Autoescales: emplaçament i seguretat","blocks":[{"text":"Per garantir l''estabilitat, l''autoescala s''ha d''emplaçar en un terreny ferm, estable i planer, fent servir correctament els estabilitzadors i evitant sobrecàrregues. No s''ha de situar sobre tapes de clavegueram, voreres, rampes inestables ni pendents pronunciats.","refs":[{"ref":"MAN.EQIP.000","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"Per garantir l’estabilitat, cal emplaçar l’autoescala en un terreny ferm, estable i planer, utilitzant correctament els estabilitzadors i evitant sobrecàrregues."},{"ref":"MAN.EQIP.000","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"No s’ha d’emplaçar sobre tapes de clavegueram, voreres, rampes inestables ni pendents pronunciats."}]},{"text":"El vent pot provocar oscil·lacions perilloses i afectar l''estabilitat del braç; per això es recomana fer servir tensors i el màxim nombre de punts de recolzament, i seguir estrictament les restriccions de funcionament. Davant del risc elèctric cal identificar el cablejat i mantenir-ne distàncies segures, assegurar l''autoescala amb una connexió correcta a terra i evitar qualsevol contacte entre l''escala i cables sota tensió, que pot ser mortal.","refs":[{"ref":"MAN.EQIP.000","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"El vent pot causar oscil·lacions perilloses i afectar l’estabilitat del braç d’escala per la qual cosa es recomana utilitzar tensors i el màxim nombre de punts de recolzament, a més de seguir estrictament les restriccions de funcionament."},{"ref":"MAN.EQIP.000","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"Pel que fa al risc elèctric, és imprescindible identificar i mantenir distàncies segures respecte al cablejat, assegurar l’autoescala amb una connexió correcta a terra i evitar qualsevol contacte entre l’escala i cables sota tensió, ja que això pot ser mortal."}]},{"text":"L''ús de l''equip de protecció individual, especialment dels sistemes anticaigudes, és obligatori per al personal que treballa en alçada. La comunicació clara i coordinada entre l''operador de l''escala, el conductor i el comandament és fonamental durant totes les maniobres.","refs":[{"ref":"MAN.EQIP.000","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"individual (EPI), especialment dels sistemes anticaigudes, és obligatori per al personal que treballa en alçada."},{"ref":"MAN.EQIP.000","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"La comunicació clara i coordinada entre l’operador de l’escala, el conductor i el comandament és fonamental durant totes les maniobres."}]}]},{"n":"7","title":"Furgons de salvament i vehicles de risc químic","blocks":[{"text":"El Furgó de Salvament (FSV) és un vehicle especialitzat destinat a donar suport en serveis de rescat tècnic, accidents de trànsit, apuntalaments i intervencions amb persones atrapades. Els furgons són essencials en el rescat tècnic i sovint actuen coordinats amb les autobombes. Els vehicles de risc químic no són als extractes revisats; cal consultar el manual MAN.EQIP.000.","refs":[{"ref":"MAN.EQIP.000","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"Furgons de salvament (FSV) El Furgó de Salvament (FSV) és un vehicle especialitzat destinat a donar suport en serveis de rescat tècnic, accidents de trànsit, apuntalaments i intervencions amb persones atrapades."},{"ref":"MAN.EQIP.000","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"Són vehicles essencials en serveis de rescat tècnic, i sovint actuen en coordinació amb les autobombes."}]}]},{"n":"8","title":"Altres vehicles: comandament, sanitaris i suport logístic","blocks":[{"text":"Des dels vehicles de comandament es coordinen els recursos operatius, es prenen les decisions tàctiques i es manté la comunicació amb els centres o sales de coordinació. Els vehicles sanitaris i de suport logístic, els protocols de treball i de seguretat amb mitjans aeris, i les consideracions operatives sobre assignació de vehicles, manteniment preventiu i revisions no són als extractes revisats; cal consultar el manual MAN.EQIP.000.","refs":[{"ref":"MAN.EQIP.000","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"És des d’aquests vehicles, on es coordinen els recursos operatius, es prenen decisions tàctiques i es manté la comunicació amb els centres o sales de coordinació."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Mitjans terrestres: els més utilitzats. Mitjans aeris: especialitzats i cars, per a accés difícil, incendis forestals intensos i rescats complexos.","refs":[{"ref":"MAN.EQIP.000","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"Els mitjans terrestres són els més utilitzats en la majoria d’emergències"}]},{"text":"Autobomba = cisterna + bomba d''impulsió + mànegues, eines i equips. Totes les del Cos: bombes centrífugues d''alta i baixa pressió.","refs":[{"ref":"MAN.EQIP.000","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"estan equipades amb bombes centrífugues d’alta i baixa pressió"}]},{"text":"BUL: 1.000-1.650 l. BUP: 3.000-4.000 l, menys maniobrable. BRP: l''estàndard dels parcs, mànegues sobretot de 25 mm. BNP: 7.000-10.000 l, fins a 5.000 l/min a 10 bars, per a grans cabals o zones sense hidrants.","refs":[{"ref":"MAN.EQIP.000 (BNP)","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"Capacitat d’aigua: entre 7.000 i 10.000 litres."}]},{"text":"AEA: treball en alçada i salvaments verticals; sense braç articulat, 20-42 m d''alçada útil.","refs":[{"ref":"MAN.EQIP.000","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"Alçada útil entre 20 i 42 metres"}]},{"text":"Grua pesada: primer tram, resta recollits, només en emergència. Grua lleugera: tot el braç, càrrega a l''extrem de l''últim tram.","refs":[{"ref":"MAN.EQIP.000","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"es fa amb tot el braç d''escala subjectant la càrrega a l''extrem de l''últim tram."}]},{"text":"AEA: terreny ferm i planer, mai sobre tapes de clavegueram, voreres o pendents; amb vent, tensors i màxim de recolzaments; risc elèctric, distàncies i presa de terra; anticaigudes obligatori.","refs":[{"ref":"MAN.EQIP.000","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"No s’ha d’emplaçar sobre tapes de clavegueram, voreres, rampes inestables ni pendents pronunciats."}]},{"text":"FSV: rescat tècnic, trànsit, apuntalaments i persones atrapades.","refs":[{"ref":"MAN.EQIP.000","law":"MAN.EQIP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf","quote":"destinat a donar suport en serveis de rescat tècnic, accidents de trànsit, apuntalaments i intervencions amb persones atrapades."}]}]}]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf', null, null, null, null
