insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Concepte de gestió d''emergències"},{"n":"2","title":"Cicle de gestió: reducció del risc, preparació, resposta i recuperació"},{"n":"3","title":"La resiliència com a eix transversal"},{"n":"4","title":"El risc: perill, vulnerabilitat i exposició; classificació i construcció social"},{"n":"5","title":"Protecció civil: concepte i evolució"},{"n":"6","title":"Organització competencial i autoritats (Llei 17/2015)"},{"n":"7","title":"Mecanisme europeu de protecció civil"},{"n":"8","title":"Plans de protecció civil: territorials, especials, municipals, PAU i estatals"},{"n":"9","title":"Estructura dels plans: direcció, Comitè d''Emergències, CECAT/CECOPAL i CCA"}]'::jsonb, '["§ protecció civil MAN.GRAL.001: «La protecció civil és el conjunt d''accions i mecanismes que les administracions públiques —i la societat en general— posen en marxa per garantir la seguretat de les persones, els béns i el medi ambient davant situacions de risc col·lectiu o catàstrofes.»","§ perill MAN.GRAL.001: «És la probabilitat que es produeixi un fenomen d’una determinada intensitat.»","§ reduir el risc MAN.GRAL.001: «Per això, per reduir el risc no sempre cal eliminar el perill (que sovint és inevitable), sinó que també es pot reduir la vulnerabilitat o limitar l’exposició.»","§ ajuntaments MAN.GRAL.001: «Àmbit local: la protecció civil municipal Els ajuntaments són la primera baula del sistema.»","§ estat MAN.GRAL.001: «Àmbit estatal: el Ministeri de l’Interior Segons la Llei 17/2015, la direcció global del sistema de protecció civil recau en el Ministeri de l’Interior que és l’autoritat de protecció civil estatal.»","§ pla de protecció civil MAN.GRAL.001: «Els plans de protecció civil Un pla de protecció civil és un document tècnic i operatiu que estableix com s''ha d''organitzar i actuar davant d’un risc determinat o en una situació d’emergència.»","§ PROCICAT MAN.GRAL.001: «Pla territorial de protecció civil de Catalunya, per a riscos generals o situacions que no tenen pla especial.»","§ CECAT MAN.GRAL.001: «El CECAT o CECOPAL com a màxim òrgan de coordinació operativa ja sigui a nivell autonòmic o municipal.»","§ ubicació CCA MAN.GRAL.001: «Habitualment el CCA s’ubica en un lloc segur, però proper a la zona més afectada per permetre una resposta àgil i adaptada al context operatiu.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"La gestió d''emergències: concepte","blocks":[{"text":"La gestió d''emergències és l''organització i l''administració dels recursos, les responsabilitats i les capacitats necessàries per afrontar tots els aspectes d''una emergència: abans, durant i després que es produeixi. No es limita, doncs, a la resposta: inclou tot el que es fa per anticipar-la i per tornar a la normalitat.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"La gestió d’emergències és l’organització i l’administració dels recursos, responsabilitats i capacitats necessàries per afrontar tots els aspectes d’una emergència, abans, durant i després que es produeixi."}]}]},{"n":"2","title":"El cicle de gestió d''emergències","blocks":[{"text":"El cicle té quatre fases: reducció del risc, preparació, resposta i recuperació. Aquestes fases no són processos seqüencials lineals, sinó un cicle continu de millora: el que s''aprèn en una emergència alimenta la reducció del risc i la preparació de la següent.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"Aquestes quatre fases no són processos seqüencials lineals, sinó un cicle continu de millora."}]},{"text":"La reducció del risc és una etapa clarament proactiva i preventiva, que actua molt abans que es desencadeni una situació de perill. La Llei 4/1997 hi respon quan obliga totes les administracions a orientar les seves actuacions a la reducció del risc.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"És una etapa clarament proactiva i preventiva, que actua molt abans que es desencadeni una situació de perill."},{"ref":"Art. 13 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"Las actuaciones de todas las Administraciones públicas en Cataluña, en el ejercicio de las competencias que les son propias, deben estar orientadas a la reducción del riesgo."}]},{"text":"La fase de preparació no es descriu als extractes revisats del manual (cal consultar el MAN.GRAL.001). La Llei 4/1997 hi associa la preparació de la població, sobretot amb campanyes d''informació i divulgació, i els simulacres.","refs":[{"ref":"Art. 35.1 i 35.3 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"El Gobierno y las entidades locales deben llevar a cabo las actividades que sean necesarias para preparar a la población ante situaciones de grave riesgo colectivo […] preparar y realizar simulacros"}]},{"text":"La resposta és la fase més visible de tot el cicle, perquè mobilitza recursos humans i materials de manera intensa i en temps real.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"És la fase més visible de tot el cicle, ja que mobilitza recursos humans i materials de manera intensa i en temps real."}]},{"text":"A la recuperació, l''objectiu no és només tornar a com estàvem, sinó millorar la resiliència col·lectiva i aprofitar l''experiència per estar més ben preparats. La Llei 4/1997 hi preveu el restabliment dels serveis essencials i un pla de recuperació de la normalitat que identifiqui i avaluï els danys.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"L’objectiu no és només tornar a com estàvem, sinó millorar la resiliència col·lectiva i aprofitar l’experiència per estar més ben preparats per al futur."},{"ref":"Art. 30.1 i 31.1 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"Los poderes públicos, dentro de sus competencias, deben restablecer los servicios esenciales para la comunidad afectados por una catástrofe o calamidad. […] La identificación y evaluación de los daños y perjuicios producidos."}]}]},{"n":"3","title":"La resiliència","blocks":[{"text":"La resiliència és l''eix transversal del cicle: la capacitat d''una persona, comunitat, organització o sistema per resistir, absorbir, adaptar-se i recuperar-se davant d''una situació adversa o una emergència.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"La resiliència és la capacitat d’una persona, comunitat, organització o sistema per resistir, absorbir, adaptar-se i recuperar-se davant d’una situació adversa o una emergència."}]}]},{"n":"4","title":"Els riscos: components, reducció i mapa de riscos","blocks":[{"text":"El risc es descompon en tres elements. El perill és la probabilitat que es produeixi un fenomen d''una determinada intensitat. La vulnerabilitat és la capacitat o incapacitat d''un element per resistir l''impacte d''aquest fenomen. L''exposició és el nombre d''elements vulnerables i el temps que estan en contacte amb el perill.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"És la probabilitat que es produeixi un fenomen d’una determinada intensitat. […] És la capacitat o incapacitat d’un element per resistir l’impacte d’aquest fenomen. […] És el nombre i el temps que aquests elements vulnerables estan en contacte amb el perill."}]},{"text":"Conseqüència pràctica: per reduir el risc no sempre cal eliminar el perill, que sovint és inevitable; també es pot reduir la vulnerabilitat o limitar l''exposició.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"per reduir el risc no sempre cal eliminar el perill (que sovint és inevitable), sinó que també es pot reduir la vulnerabilitat o limitar l’exposició."}]},{"text":"La definició general de risc i la seva classificació (naturals, tecnològics, antròpics…) no són als extractes revisats; cal consultar el manual MAN.GRAL.001. Pel que fa al mapa de riscos, la Llei 4/1997 crea el Mapa de protecció civil de Catalunya: el conjunt de mapes temàtics que mostren les zones on es presenta cada risc, que el Departament revisa periòdicament.","refs":[{"ref":"Art. 12.1 i 12.3 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"El Mapa es el conjunto de mapas temáticos en el que se ponen de manifiesto las distintas zonas territoriales en las que se presenta cada riesgo. […] El Mapa debe ser revisado periódicamente por parte del Departamento de Gobernación."}]}]},{"n":"5","title":"El sistema de protecció civil: concepte i evolució","blocks":[{"text":"La protecció civil és el conjunt d''accions i mecanismes que les administracions públiques —i la societat en general— posen en marxa per garantir la seguretat de les persones, els béns i el medi ambient davant situacions de risc col·lectiu o catàstrofes. La Llei 4/1997 la defineix en termes semblants (risc greu col·lectiu, catàstrofes i calamitats públiques).","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"La protecció civil és el conjunt d''accions i mecanismes que les administracions públiques —i la societat en general— posen en marxa per garantir la seguretat de les persones, els béns i el medi ambient davant situacions de risc col·lectiu o catàstrofes."},{"ref":"Art. 1.1 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"comprende las acciones destinadas a la protección de las personas, los bienes y el medio ambiente ante situaciones de grave riesgo colectivo, catástrofes y calamidades públicas."}]},{"text":"Sobre l''evolució, el preàmbul de la Llei 4/1997 explica que la protecció civil no figura com a títol competencial ni a la Constitució ni a l''Estatut; l''única referència és l''art. 30.4 CE (deures dels ciutadans en casos de risc greu, catàstrofe o calamitat pública), i el Tribunal Constitucional l''ha integrat com una vessant de la seguretat pública, amb competències concurrents. L''evolució històrica més detallada no és a les fonts revisades.","refs":[{"ref":"Preàmbul Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"El Tribunal Constitucional ha subsanado el vacío competencial integrando la protección civil como una vertiente de la seguridad pública, materia sobre la que se dan competencias concurrentes entre las distintas Administraciones públicas."}]}]},{"n":"6","title":"Organització competencial i autoritats: àmbits local i autonòmic","blocks":[{"text":"La Llei 17/2015, del Sistema Nacional de Protecció Civil, estableix quines són les autoritats competents a cada àmbit administratiu per dirigir i activar les respostes davant d''una emergència.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"La Llei 17/2015, del Sistema Nacional de Protecció Civil, estableix quines són les autoritats competents a cada àmbit administratiu per dirigir i activar les respostes davant una emergència."}]},{"text":"Àmbit local: els ajuntaments són la primera baula del sistema. Els municipis de més de 20.000 habitants estan obligats a tenir un servei municipal de protecció civil amb caràcter general. L''alcalde és l''autoritat municipal de protecció civil, responsable d''elaborar i activar els plans municipals, dels quals exerceix la direcció.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"Els ajuntaments són la primera baula del sistema. […] Els municipis de més de 20.000 habitants estan obligats a disposar d’un servei municipal de protecció civil amb caràcter general. […] L’alcalde és l’autoritat municipal de protecció civil, responsable de l’elaboració i activació dels plans municipals dels quals n’exerceix la direcció"}]},{"text":"Àmbit autonòmic: l''autoritat de protecció civil és el conseller o consellera d''Interior. La Llei 4/1997 (que encara diu «Governació») el qualifica d''autoritat superior de protecció civil de Catalunya, i el Govern és l''òrgan col·legiat superior de direcció i coordinació.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"A nivell autonòmic, l’autoritat de protecció civil és el conseller o consellera d’Interior"},{"ref":"Art. 42.1 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"El Gobierno de la Generalidad es el órgano colegiado superior de dirección y coordinación de protección civil de Cataluña."}]}]},{"n":"7","title":"Àmbits estatal i europeu","blocks":[{"text":"Àmbit estatal: segons la Llei 17/2015, la direcció global del sistema de protecció civil recau en el Ministeri de l''Interior, que és l''autoritat de protecció civil estatal.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"Segons la Llei 17/2015, la direcció global del sistema de protecció civil recau en el Ministeri de l’Interior que és l’autoritat de protecció civil estatal."}]},{"text":"Àmbit europeu: el Mecanisme europeu de protecció civil, creat l''any 2001, és un sistema de cooperació entre estats europeus per millorar la prevenció, la preparació i la resposta conjunta davant desastres naturals, tecnològics o d''origen humà, tant dins com fora de la Unió Europea.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"El Mecanisme, creat l’any 2001, és un sistema de cooperació entre estats europeus que té com a objectiu millorar la prevenció, la preparació i la resposta conjunta davant de desastres naturals, tecnològics o d’origen humà, tant dins com fora de la Unió Europea."}]}]},{"n":"8","title":"Plans de protecció civil: concepte i tipus","blocks":[{"text":"Un pla de protecció civil és un document tècnic i operatiu que estableix com s''ha d''organitzar i actuar davant d''un risc determinat o d''una emergència. La Llei 4/1997 en distingeix tres classes: territorials, especials i d''autoprotecció.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"Un pla de protecció civil és un document tècnic i operatiu que estableix com s''ha d''organitzar i actuar davant d’un risc determinat o en una situació d’emergència."},{"ref":"Art. 15.1 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"Los planes de protección civil pueden ser territoriales, especiales y de autoprotección."}]},{"text":"Plans de Catalunya: el PROCICAT és el pla territorial de protecció civil de Catalunya, per a riscos generals o situacions sense pla especial. Els plans especials (INFOCAT, INUNCAT, PLASEQCAT…) tracten emergències associades a riscos concrets al territori de Catalunya.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"Pla territorial de protecció civil de Catalunya, per a riscos generals o situacions que no tenen pla especial. […] Plans especials com l’INFOCAT, INUNCAT, PLASEQCAT..., són plans per a emergències associades a riscos concrets, en el territori de Catalunya."}]},{"text":"Plans municipals: els diferents PAM (plans d''actuació municipal) per a riscos concrets i el Pla bàsic municipal s''integren en un document únic de la protecció civil municipal anomenat DUPROCIM.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"Els diferents PAM municipals per a riscos concrets, així com el Pla bàsic municipal, s’integren en un document únic de la protecció civil municipal anomenat DUPROCIM."}]},{"text":"Plans d''autoprotecció (PAU): els elaboren les activitats privades o públiques que poden generar un risc o veure''s afectades per una emergència.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"Els plans d’autoprotecció (PAU) són elaborats per activitats privades o públiques que poden generar un risc o veure’s afectades per una emergència."}]},{"text":"Plans estatals: destaca el Pla Estatal General d''Emergències (PLEGEM), pla operatiu que engloba i integra tots els plans estatals i autonòmics, amb especial atenció a les emergències multirisc (baixa probabilitat però gran impacte).","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"Destaca el Pla Estatal General d’Emergències (PLEGEM), és el pla operatiu que engloba i integra tots els plans estatals i autonòmics, amb especial atenció a les emergències multirisc (baixa probabilitat, però gran impacte)."}]}]},{"n":"9","title":"Continguts bàsics i estructura dels plans","blocks":[{"text":"Segons la Llei 4/1997, tots els plans tenen una estructura de contingut homogènia que inclou, com a mínim: característiques del territori i de la població, anàlisi de riscos, actuacions de prevenció i d''emergència, comitè d''emergència, serveis operatius, mitjans i recursos, infraestructures operatives, nivells d''aplicació (alarma i emergència), procediment d''activació, relació amb altres plans, mesures d''informació i protecció de la població, rehabilitació, implantació i simulacres, i manteniment del pla.","refs":[{"ref":"Art. 20.1 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"Los planes de protección civil deben ser elaborados según una estructura de contenido homogénea, a efectos de su integración […] h) Los niveles de aplicación del plan, que deben corresponderse con situaciones de alarma y emergencia"}]},{"text":"Les infraestructures operatives mínimes són un centre receptor d''alarmes, un centre de coordinació operativa i els centres de comandament avançat. Els plans s''han de revisar cada quatre anys.","refs":[{"ref":"Art. 20.1.g i 24.2 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"un centro receptor de alarmas, un centro de coordinación operativa y los centros de mando avanzado. […] Todos los planes deben ser revisados cada cuatro años."}]}]},{"n":"10","title":"Organització operativa: direcció del pla, Comitè d''Emergències, CCA, grups actuants i voluntariat","blocks":[{"text":"Direcció del pla: en els plans de protecció civil de Catalunya, recau en el conseller o consellera d''Interior, o en la persona en qui delegui, sempre en coordinació amb els alcaldes dels municipis afectats.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"En el cas dels plans de protecció civil de Catalunya, aquesta funció recau en el/la conseller/a d’Interior, o en la persona en qui delegui, i es desenvolupa sempre en coordinació amb els alcaldes dels municipis afectats."}]},{"text":"Quan s''activa un pla, es constitueix un Comitè d''Emergències, que és l''òrgan responsable de prendre les decisions estratègiques i dirigir la resposta. Segons la llei, el comitè l''integren el director del pla, el consell assessor i el gabinet d''informació.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"Quan s’activa un pla de protecció civil, es constitueix un Comitè d’Emergències, que és l’òrgan responsable de prendre les decisions estratègiques i dirigir la resposta."},{"ref":"Art. 20.1.d Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"El comité de emergencia, integrado por el director o directora del plan"}]},{"text":"El Centre de Comandament Avançat (CCA) és l''espai des d''on es dirigeixen totes les actuacions in situ durant una emergència. Habitualment s''ubica en un lloc segur però proper a la zona més afectada, per permetre una resposta àgil i adaptada.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"El Centre de Comandament Avançat (CCA) és l’espai des d’on es dirigeixen totes les actuacions in situ durant una emergència. […] Habitualment el CCA s’ubica en un lloc segur, però proper a la zona més afectada per permetre una resposta àgil i adaptada al context operatiu."}]},{"text":"Grups actuants: els serveis operatius dels plans s''organitzen, com a mínim, en grups d''intervenció, d''ordre, sanitari i logístic. La composició i funcions detallades de cada grup no són als extractes revisats del manual.","refs":[{"ref":"Art. 20.1.e Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"Los servicios operativos, que se organizan, como mínimo, en los grupos de intervención, de orden, sanitario y logístico"}]},{"text":"Voluntariat: la ciutadania pot col·laborar regularment, de manera voluntària i desinteressada, a través de les associacions de voluntaris de protecció civil; els plans només en poden reconèixer una per municipi, que determina l''ajuntament.","refs":[{"ref":"Art. 54 i 55.2 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"Los ciudadanos y ciudadanas pueden colaborar regularmente de forma voluntaria y desinteresada en las funciones de protección civil […] Los planes de protección civil sólo pueden reconocer una asociación de voluntarios y voluntarias de protección civil por municipio."}]}]},{"n":"11","title":"Mesures de protecció a la població, centres de coordinació, comunicacions i autoprotecció","blocks":[{"text":"Mesures de protecció a la població que pot acordar l''autoritat de protecció civil: evacuar o allunyar les persones dels llocs de perill, recomanar el confinament a casa o en llocs segurs, restringir l''accés a zones de perill o d''operació, i limitar l''ús de serveis i el consum de béns.","refs":[{"ref":"Art. 9 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"a) Evacuar o alejar a las personas de los sitios de peligro. b) Recomendar el confinamiento de personas en sus domicilios o en sitios seguros, de acuerdo con las previsiones de los correspondientes planes. c) Restringir el acceso a zonas de peligro o zonas de operación."}]},{"text":"Centres de coordinació: el CECAT (autonòmic) o el CECOPAL (municipal) és el màxim òrgan de coordinació operativa. La Llei 4/1997 defineix el CECAT com el centre superior de coordinació i informació de l''estructura de protecció civil de Catalunya, i obliga els CECOPAL a actuar coordinats amb el CECAT.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"El CECAT o CECOPAL com a màxim òrgan de coordinació operativa ja sigui a nivell autonòmic o municipal."},{"ref":"Art. 45.1 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"es el centro superior de coordinación e información de la estructura de protección civil de Cataluña"}]},{"text":"Sistemes de comunicació: el Govern ha de crear una xarxa general d''alarmes i comunicacions de protecció civil, i els mitjans de comunicació públics i privats han de difondre de manera prioritària, immediata i gratuïta els avisos de les autoritats. Els sistemes concrets (xarxes de radiocomunicació, avisos a mòbils…) no són als extractes revisats.","refs":[{"ref":"Art. 22.1 i 11 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"El Gobierno ha de crear una red general de alarmas y comunicaciones de protección civil. […] deben transmitir o, si procede, publicar, de forma prioritaria e inmediata, si la emergencia así lo requiere, y gratuita la información"}]},{"text":"Divulgació en autoprotecció: les administracions han de preparar la població amb campanyes d''informació i divulgació; als centres escolars és obligatori programar activitats de protecció civil i fer, almenys un cop l''any, un simulacre d''evacuació.","refs":[{"ref":"Art. 36 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"debe realizarse, al menos una vez al año, un simulacro de evacuación"}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Gestió d''emergències = recursos, responsabilitats i capacitats per a abans, durant i després. Quatre fases en cicle continu de millora, no lineal.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"sinó un cicle continu de millora."}]},{"text":"Reducció del risc: proactiva i preventiva. Resposta: la fase més visible. Recuperació: millorar la resiliència, no només tornar a com estàvem.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"És la fase més visible de tot el cicle"}]},{"text":"Risc: perill (probabilitat d''un fenomen d''una intensitat), vulnerabilitat (capacitat o incapacitat de resistir-lo) i exposició (nombre i temps de contacte).","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"És el nombre i el temps que aquests elements vulnerables estan en contacte amb el perill."}]},{"text":"Autoritats: alcalde (municipal), conseller d''Interior (Catalunya), Ministeri de l''Interior (Estat), segons la Llei 17/2015. Mecanisme europeu: 2001.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"L’alcalde és l’autoritat municipal de protecció civil"}]},{"text":"Municipis de més de 20.000 habitants: servei municipal de protecció civil obligatori. PAM + Pla bàsic municipal = DUPROCIM.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"s’integren en un document únic de la protecció civil municipal anomenat DUPROCIM."}]},{"text":"PROCICAT = pla territorial; INFOCAT, INUNCAT, PLASEQCAT = especials; PAU = autoprotecció; PLEGEM = pla estatal que integra tots, multirisc.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"Destaca el Pla Estatal General d’Emergències (PLEGEM)"}]},{"text":"Comitè d''Emergències = decisions estratègiques. CCA = direcció in situ, lloc segur proper a la zona afectada. CECAT/CECOPAL = màxim òrgan de coordinació operativa.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"El Centre de Comandament Avançat (CCA) és l’espai des d’on es dirigeixen totes les actuacions in situ durant una emergència."}]}]}]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t21-gestio-emergencies-proteccio-civil'
