   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.SP.000 Prevenció d''incendis bàsica (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t23-prevencio-incendis', 'Tema 23. Prevenció bàsica d''incendis') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t23-prevencio-incendis' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Protecció activa i passiva"},{"n":"2","title":"Marc normatiu: Llei 3/2010, CTE DB SI, RSCIEI i reglaments específics"},{"n":"3","title":"Accés per l''exterior: vies d''intervenció, espais de maniobra i façanes accessibles"},{"n":"4","title":"Accés per l''interior: vies de penetració protegides"},{"n":"5","title":"Límits a l''extensió de l''incendi: reacció i resistència al foc (R, E, I)"},{"n":"6","title":"Sectorització, façanes, cobertes i mur tallafocs"},{"n":"7","title":"Instal·lacions de protecció i sistemes de ventilació de fums"}]'::jsonb, '["§ règim sancionador MAN.SP.000: «Un altre aspecte innovador d’aquesta Llei és la creació d’un règim sancionador específic que permet corregir els incompliments de la normativa contra incendis vigent i que es poden detectar mitjançant la funció inspectora atribuïda al personal competent de la Generalitat de Catalunya.»","§ accés exterior MAN.SP.000: «Accés per l’exterior: l’arribada dels bombers al sinistre El DB SI del CTE, en la secció SI 5, i el RSCIEI, en la secció 4 de l’annex II, regulen les condicions d’intervenció dels serveis d’extinció i salvament i l’accessibilitat des de l’exterior als edificis i establiments industrials.»","§ obertures d''accés MAN.SP.000: «Les obertures d’accés són forats en façana (portals i finestres, bàsicament) amb unes dimensions i separació regulades normativament.»","§ sector diferenciat MAN.SP.000: «Una altra via de penetració vàlida, però amb menor grau de seguretat són aquelles que es realitzen per un sector d’incendi diferenciat.»","§ aïllament tèrmic MAN.SP.000: «Aïllament tèrmic (I): el criteri d’aïllament tèrmic (I) es refereix a la capacitat d’un element constructiu de separació per impedir el pas de la calor durant un temps expressat en minuts, a partir dels resultats d’un assaig de resistència al foc.»","§ parets no portants MAN.SP.000: «Parets no portants entre sectors d’incendi: només han de garantir integritat i aïllament tèrmic (EI-t).»","§ ventilació de fums MAN.SP.000: «Sistemes de ventilació de fums d’incendi Els sistemes de ventilació de fums són instal·lacions que la normativa exigeix en alguns edificis i que disposen d’un conjunt d’obertures o equips mecànics d’extracció (ventiladors) per a l’evacuació de fums i gasos calents de la combustió d’un incendi, i si és el cas, d’obertures d’admissió d’aire net o equips mecànics d’aportació.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Introducció a la prevenció d''incendis: exigències en edificis i mesures de protecció","blocks":[{"text":"La prevenció d''incendis no és només apagar focs: implica disposar de mitjans personals i materials, informar i conscienciar la societat i fer totes les accions que tendeixin a disminuir el risc. Per això els edificis han de complir unes exigències de seguretat que s''agrupen en dos grans blocs de mesures de protecció: les actives i les passives.","refs":[{"ref":"Llei 5/1994, exposició de motius","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"La prevención de incendios es una función que implica disposición de medios personales y materiales, información y concienciación de la sociedad y ejecución de cuantas acciones tiendan a disminuir su riesgo."}]},{"text":"Les mesures de protecció activa són les encaminades a detectar l''incendi, transmetre l''alarma als ocupants de l''edifici i extingir l''incendi o limitar-ne la propagació. Per funcionar necessiten, en general, que algú (els ocupants o els equips d''intervenció) les posi en marxa o hi actuï.","refs":[{"ref":"MAN.SP.000, protecció activa","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"Mesures de protecció activa: són mesures de seguretat encaminades a detectar l’incendi, transmetre l’alarma als ocupants de l’edifici i extingir l’incendi o limitar-ne la seva propagació."}]},{"text":"Les mesures de protecció passiva, en canvi, les ofereix l''edifici per si mateix gràcies al seu disseny i als materials emprats en la construcció, i en general no necessiten la interacció dels ocupants ni dels equips intervinents per funcionar. Hi pertanyen, per exemple, la sectorització, la resistència i la reacció al foc dels elements i les condicions d''accés per als bombers que es veuen als apartats següents.","refs":[{"ref":"MAN.SP.000, protecció passiva","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"Actuen de forma passiva a l’edifici, és a dir, són mesures de seguretat que l’edifici ja ofereix per sí mateix gràcies al seu disseny i als materials emprats en la seva construcció, i en general no precisen necessàriament de la interacció dels ocupants o dels equips intervinents per funcionar."}]}]},{"n":"2","title":"Organització preventiva: el paper dels Bombers i de l''administració","blocks":[{"text":"La Llei 5/1994 atribueix al Cos de Bombers de la Generalitat, entre les seves funcions, fer activitats de prevenció per evitar o disminuir el risc d''incendis i d''accidents. En els municipis sense servei municipal de prevenció i extinció, li correspon emetre informe sobre els projectes de nova construcció, de reforma i d''activitats abans de l''autorització de l''autoritat competent, i inspeccionar establiments i locals públics per comprovar que compleixen la normativa de prevenció d''incendis. També estudia i investiga les tècniques, les instal·lacions i els sistemes de protecció contra incendis (art. 13 b i c L5).","refs":[{"ref":"Art. 13.b) L5","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"b) Realizar actividades de prevención tendentes a evitar o disminuir el riesgo de incendios y de accidentes, en el marco de la normativa específica para cada ámbito. Entre estas actividades, le corresponde, en los municipios carentes de servicios municipales de prevención y extinción de incendios, emitir informe, en la forma que se determine por reglamento, previamente a la autorización de la autoridad competente, sobre los proyectos de nueva construcción, de reforma y de actividades, así como inspeccionar los establecimientos y los locales públicos con la finalidad de determinar el cumplimiento de la normativa de prevención de incendios."},{"ref":"Art. 13.c) L5","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"c) Estudiar e investigar las técnicas, las instalaciones y los sistemas para la protección contra incendios en relación a la normativa específica en esta materia."}]},{"text":"Les instal·lacions de protecció contra incendis les munten i les mantenen empreses especialitzades. A Catalunya, l''autorització de les empreses instal·ladores i mantenidores és competència de l''òrgan competent en matèria d''indústria, que és qui en porta el registre (no dels Bombers ni dels ajuntaments).","refs":[{"ref":"MAN.SP.000, empreses instal·ladores","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"L''autorització de les empreses instal·ladores i mantenidores és competència de l''òrgan competent en matèria d''indústria a Catalunya que és qui en porta el corresponent registre."}]}]},{"n":"3","title":"Marc normatiu: Llei 3/2010, CTE DB SI i RSCIEI","blocks":[{"text":"La norma catalana de referència és la Llei 3/2010, de prevenció i seguretat en matèria d''incendis en establiments, activitats, infraestructures i edificis. Determina quins actes, procediments i òrgans administratius tenen competències en cadascuna de les parts del procés de sol·licitud de llicència.","refs":[{"ref":"MAN.SP.000, Llei 3/2010","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"La Llei 3/2010, de Prevenció i seguretat en matèria d’incendis en establiments, activitats, infraestructures i edificis determina quins seran els actes, procediments i òrgans administratius amb competències en cadascuna de les parts del procés de sol·licitud de llicència."}]},{"text":"Un aspecte innovador de la Llei 3/2010 és la creació d''un règim sancionador específic, que permet corregir els incompliments de la normativa contra incendis detectats mitjançant la funció inspectora atribuïda al personal competent de la Generalitat.","refs":[{"ref":"MAN.SP.000, règim sancionador","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"Un altre aspecte innovador d’aquesta Llei és la creació d’un règim sancionador específic que permet corregir els incompliments de la normativa contra incendis vigent i que es poden detectar mitjançant la funció inspectora atribuïda al personal competent de la Generalitat de Catalunya."}]},{"text":"Les condicions tècniques es troben sobretot en dues normes estatals: el Document Bàsic de Seguretat en cas d''Incendi del Codi Tècnic de l''Edificació (CTE DB SI), per als edificis en general, i el Reglament de seguretat contra incendis en establiments industrials (RSCIEI), per als establiments industrials. Pel que fa a l''RSCIEI, el règim transitori permet continuar aplicant l''anterior reglament, aprovat pel RD 2267/2004, a les obres que ja estaven en execució o que tenien sol·licitada la llicència municipal d''obres en aquella data, sempre que es compleixin els terminis establerts.","refs":[{"ref":"MAN.SP.000, règim transitori","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"El règim transitori permet continuar aplicant l’anterior RSCIEI, aprovat pel RD 2267/2004, a les obres que ja estaven en execució o que tenien sol·licitada la llicència municipal d’obres en aquella data, sempre que es compleixin els terminis establerts."}]},{"text":"Les fonts revisades no recullen la data ni la norma que aprova el nou RSCIEI que substitueix el del RD 2267/2004; cal consultar el manual MAN.SP.000 complet per a aquest detall.","refs":[{"ref":"MAN.SP.000, règim transitori","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"permet continuar aplicant l’anterior RSCIEI, aprovat pel RD 2267/2004"}]}]},{"n":"4","title":"Accés per l''exterior: vies o carrers d''intervenció","blocks":[{"text":"L''arribada dels bombers al sinistre està regulada: el CTE DB SI ho fa a la secció SI 5 i l''RSCIEI a la secció 4 de l''annex II, que fixen les condicions d''intervenció dels serveis d''extinció i salvament i l''accessibilitat des de l''exterior als edificis i establiments industrials.","refs":[{"ref":"MAN.SP.000, accés exterior","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"Accés per l’exterior: l’arribada dels bombers al sinistre El DB SI del CTE, en la secció SI 5, i el RSCIEI, en la secció 4 de l’annex II, regulen les condicions d’intervenció dels serveis d’extinció i salvament i l’accessibilitat des de l’exterior als edificis i establiments industrials."}]},{"text":"Les vies o carrers d''intervenció (també anomenats vials d''aproximació) són les vies públiques per on els vehicles de bombers es desplacen des del parc d''origen fins a la zona d''emplaçament, situada davant d''una façana accessible de l''edifici sinistrat.","refs":[{"ref":"MAN.SP.000, vies d''intervenció","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"Les vies o carrers d’intervenció Les vies o carrers d’intervenció, o vials d''aproximació, són vies públiques per les quals els vehicles de bombers es desplacen des del parc d’origen fins a la zona d’emplaçament, situada davant d’una façana accessible de l’edifici sinistrat."}]},{"text":"A més del CTE i l''RSCIEI, marquen les condicions d''aquests elements el document DT-12 de la Taula d''Interpretació de la Normativa de Seguretat Contra Incendis (TINSCI) i la instrucció tècnica complementària SP113 de la DGPEIS, que regula els casos de vials d''accés sense sortida.","refs":[{"ref":"MAN.SP.000, DT-12 i SP113","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"Un altre document que marca les condicions d’aquests elements és el document DT-12 elaborat per la Taula d’Interpretació de la Normativa de Seguretat Contra Incendis (TINSCI) així com la instrucció tècnica complementària SP113 de la DGPEIS que regula els casos de vials d’accés sense sortida."}]}]},{"n":"5","title":"Emplaçament de vehicles: espais de maniobra","blocks":[{"text":"Els espais de maniobra són la zona on s''emplacen els vehicles davant la façana. Les seves característiques es regulen, bàsicament, per als edificis de més de 9 metres d''alçada d''evacuació (aproximadament planta baixa + 3 pisos) i, en el cas d''establiments industrials, també quan la superfície en planta supera els 1.000 m². Les dimensions concretes d''aquests espais (amplada, pendent, resistència del paviment) no són a les fonts revisades; cal consultar el manual MAN.SP.000.","refs":[{"ref":"MAN.SP.000, espais de maniobra","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"Bàsicament, les característiques dels espais de maniobra es regulen per als edificis de més de 9 metres d’alçada d’evacuació (aproximadament planta baixa + 3 pisos) o en el cas d’establiments industrials també si la seva superfície en planta supera els 1.000 m2."}]}]},{"n":"6","title":"Façanes accessibles i obertures d''accés","blocks":[{"text":"Es considera façana accessible la que disposa d''obertures que permeten l''accés dels bombers des de l''exterior a cada planta o forjat ocupat. Aquestes obertures d''accés són forats en façana, bàsicament portals i finestres, amb unes dimensions i una separació regulades normativament.","refs":[{"ref":"MAN.SP.000, façana accessible","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"Es considera façana accessible d’un edifici aquella que disposi d’obertures per permetre l’accés dels bombers des de l’exterior a cada planta o forjat ocupat."},{"ref":"MAN.SP.000, obertures d''accés","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"Les obertures d’accés són forats en façana (portals i finestres, bàsicament) amb unes dimensions i separació regulades normativament."}]},{"text":"En els establiments industrials, la longitud de façana accessible ha de ser, amb caràcter general, com a mínim el 15 % del perímetre de la planta de l''edifici, sens perjudici de les reduccions o increments justificats que preveu l''RSCIEI.","refs":[{"ref":"MAN.SP.000, establiments industrials","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"En els establiments industrials, la longitud de façana accessible ha de ser, amb caràcter general, com a mínim del 15 % del perímetre de la planta de l’edifici, sens perjudici de les reduccions o increments justificats que preveu el RSCIEI."}]}]},{"n":"7","title":"Recorreguts interiors: vies de penetració","blocks":[{"text":"Un cop a l''edifici, els bombers han de triar per on entrar. Les vies de penetració protegides han de ser les prioritàries, perquè són les que garanteixen un alt grau de seguretat. Una altra via vàlida, però amb menys grau de seguretat, és la que es fa a través d''un sector d''incendi diferenciat.","refs":[{"ref":"MAN.SP.000, vies protegides","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"Les vies de penetració protegides han de ser les vies de penetració prioritàries per als bombers i són aquelles que garanteixen un alt grau de seguretat."},{"ref":"MAN.SP.000, sector diferenciat","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"Una altra via de penetració vàlida, però amb menor grau de seguretat són aquelles que es realitzen per un sector d’incendi diferenciat."}]},{"text":"A la planta de sortida de l''edifici, el recorregut des de la porta de sortida del recinte de l''escala protegida (o, si no n''hi ha, des del seu desembarcament) fins a una sortida de l''edifici no pot superar els 15 metres, excepte quan es fa per un sector de risc mínim, cas en què s''aplica el límit propi d''aquest sector.","refs":[{"ref":"MAN.SP.000, planta de sortida","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"A la planta de sortida de l’edifici, la longitud del recorregut des de la porta de sortida del recinte de l’escala protegida —o, si no n’hi ha, des del seu desembarcament— fins a una sortida de l’edifici no ha de superar els 15 metres, excepte quan el recorregut es faci per un sector de risc mínim, cas en què s’aplica el límit corresponent a aquest sector."}]}]},{"n":"8","title":"Límits a l''extensió de l''incendi: comportament dels materials (reacció al foc)","blocks":[{"text":"La reacció al foc és una propietat dels materials: és la resposta del material mesurada segons la contribució que fa al desenvolupament del foc amb la seva pròpia combustió, en condicions específiques d''assaig. No s''ha de confondre amb la resistència al foc, que és pròpia dels elements constructius.","refs":[{"ref":"MAN.SP.000, reacció al foc","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"Reacció al foc La reacció al foc d’un material és la resposta que té aquest material mesurada segons la contribució que realitza al desenvolupament del foc mitjançant la seva pròpia combustió, sota condicions específiques d’assaig."}]},{"text":"La classificació de reacció al foc inclou indicadors complementaris. La lletra «d» es refereix a la caiguda de gotes i partícules inflamades: la classe d1 vol dir sense caiguda de gotes i partícules inflamades durant més de 10 s. La resta de classes (principals i de producció de fum) no surten a les fonts revisades; cal consultar el manual MAN.SP.000.","refs":[{"ref":"MAN.SP.000, classe d1","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"d1- sense caiguda de gotes i partícules inflamades durant més de 10 s"}]}]},{"n":"9","title":"Resistència al foc dels elements: R, E i I","blocks":[{"text":"La resistència al foc d''un element constructiu és la capacitat de mantenir durant un temps determinat la funció portant (R) que se li exigeix i també la integritat (E) i/o l''aïllament tèrmic (I), segons l''assaig normalitzat corresponent.","refs":[{"ref":"MAN.SP.000, resistència al foc","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"Resistència al foc Es defineix la resistència al foc d''un element constructiu com la capacitat d’aquest per mantenir durant un període de temps determinat la funció portant (R) que se li exigeixi, així com la integritat (E) i/o l’aïllament tèrmic (I) segons els termes especificats a l’assaig normalitzat corresponent."}]},{"text":"La integritat (E) és la capacitat d''un element exposat al foc per una cara de prevenir el pas de flames i gasos calents, o l''aparició de flames a la cara no exposada, durant el temps de l''assaig. L''aïllament tèrmic (I) és la capacitat d''un element de separació d''impedir el pas de la calor durant un temps expressat en minuts. Recordatori: R = portant, E = integritat (flames i gasos), I = aïllament (calor).","refs":[{"ref":"MAN.SP.000, integritat","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"Integritat (E): un element constructiu exposat al foc en un dels seus costats es defineix amb el concepte d’integritat (E) quan té la capacitat de prevenir el pas de les flames i de gasos calents o l’aparició de flames a la cara no exposada durant un temps establert en un assaig normalitzat de resistència al foc."},{"ref":"MAN.SP.000, aïllament tèrmic","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"Aïllament tèrmic (I): el criteri d’aïllament tèrmic (I) es refereix a la capacitat d’un element constructiu de separació per impedir el pas de la calor durant un temps expressat en minuts, a partir dels resultats d’un assaig de resistència al foc."}]},{"text":"Aplicat als elements que separen sectors d''incendi: les parets no portants només han de garantir integritat i aïllament tèrmic (EI-t); les portes de pas entre sectors han de garantir integritat i aïllament tèrmic, especificar el tipus d''aïllament i tenir mecanisme de tancament automàtic (EI2-t-C5); i les portes d''ascensors i muntacàrregues que comuniquen sectors diferents només han de garantir la integritat (E-t). La «t» indica el temps exigit en minuts.","refs":[{"ref":"MAN.SP.000, parets no portants","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"Parets no portants entre sectors d’incendi: només han de garantir integritat i aïllament tèrmic (EI-t)."},{"ref":"MAN.SP.000, portes de pas","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"Portes de pas entre sectors d’incendi: han de garantir integritat i aïllament tèrmic, a més d’especificar el tipus d’aïllament utilitzat, disposar de mecanisme de tancament automàtic (EI2-t-C5)."},{"ref":"MAN.SP.000, portes d''ascensor","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"Portes d’ascensors i muntacàrregues que comuniquin diferents sectors d’incendi: només han de garantir la integritat (E-t)."}]}]},{"n":"10","title":"Propagació exterior: el mur tallafocs","blocks":[{"text":"Per limitar el risc de propagació entre edificacions o sectors veïns, sobretot a nivell de coberta, s''utilitza el mur tallafocs, que és una prolongació de la paret mitgera per sobre de la coberta. Les altres mesures contra la propagació exterior per façana (franges, distàncies entre obertures) no són a les fonts revisades; cal consultar el manual MAN.SP.000 i el CTE DB SI.","refs":[{"ref":"MAN.SP.000, mur tallafocs","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"Un altre element que permet limitar el risc de propagació entre edificacions o sectors veïns, especialment a nivell de coberta, és el mur tallafocs, entenent aquest com una prolongació de la paret mitgera per sobre de la coberta."}]}]},{"n":"11","title":"Recursos de lluita contra incendis: control i evacuació de fums","blocks":[{"text":"Els sistemes de ventilació de fums són instal·lacions que la normativa exigeix en alguns edificis. Consten d''un conjunt d''obertures o d''equips mecànics d''extracció (ventiladors) per evacuar els fums i gasos calents de la combustió i, si escau, d''obertures d''admissió d''aire net o equips mecànics d''aportació.","refs":[{"ref":"MAN.SP.000, ventilació de fums","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"Sistemes de ventilació de fums d’incendi Els sistemes de ventilació de fums són instal·lacions que la normativa exigeix en alguns edificis i que disposen d’un conjunt d’obertures o equips mecànics d’extracció (ventiladors) per a l’evacuació de fums i gasos calents de la combustió d’un incendi, i si és el cas, d’obertures d’admissió d’aire net o equips mecànics d’aportació."}]},{"text":"La ventilació natural funciona per les forces de flotació que resulten de la diferència de densitat i temperatura dels gasos (el gas calent, més lleuger, puja i surt); la mecànica fa servir ventiladors. Els hidrants, la columna seca, l''abastament d''aigua i els sistemes d''extinció automàtica, que també formen part d''aquest punt de l''epígraf, no són a les fonts revisades; cal consultar el manual MAN.SP.000.","refs":[{"ref":"MAN.SP.000, ventilació natural","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"Sistema de ventilació natural La ventilació natural és provocada per les forces de flotació derivades de la diferència de densitat i temperatura dels gasos."}]}]},{"n":"12","title":"Prevenció operativa i divulgació de la seguretat","blocks":[{"text":"La Llei 5/1994 encomana al Cos de Bombers fer activitats informatives i formatives per a la població que limitin les causes i les conseqüències dels incendis i dels accidents i augmentin l''autoprotecció de la ciutadania. El Catàleg d''elements de risc (CER), les fitxes operatives d''elements de risc (FOER) i el seu cicle de gestió no són a les fonts revisades; cal consultar el manual MAN.SP.000.","refs":[{"ref":"Art. 13.h) L5","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"h) Llevar a cabo actividades informativas y formativas para la población en general que persigan limitar las causas y las consecuencias de los incendios y de los accidentes y aumentar la autoprotección de la ciudadanía."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Activa = detectar, alarmar, extingir o limitar (necessita interacció). Passiva = la dona l''edifici pel disseny i els materials, sense interacció.","refs":[{"ref":"MAN.SP.000, protecció activa","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"Mesures de protecció activa: són mesures de seguretat encaminades a detectar l’incendi, transmetre l’alarma als ocupants de l’edifici i extingir l’incendi o limitar-ne la seva propagació."}]},{"text":"Llei 3/2010 (Catalunya): procés de llicència i règim sancionador propi. Anterior RSCIEI: RD 2267/2004. SP113 (DGPEIS): vials d''accés sense sortida. DT-12: TINSCI.","refs":[{"ref":"MAN.SP.000, SP113","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"la instrucció tècnica complementària SP113 de la DGPEIS que regula els casos de vials d’accés sense sortida"}]},{"text":"Empreses instal·ladores i mantenidores: les autoritza i registra l''òrgan competent en matèria d''indústria.","refs":[{"ref":"MAN.SP.000, empreses instal·ladores","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"L''autorització de les empreses instal·ladores i mantenidores és competència de l''òrgan competent en matèria d''indústria a Catalunya"}]},{"text":"Espais de maniobra: edificis de més de 9 m d''alçada d''evacuació (≈ PB+3) o industrials de més de 1.000 m² en planta. Façana accessible industrial: mínim 15 % del perímetre.","refs":[{"ref":"MAN.SP.000, espais de maniobra","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"edificis de més de 9 metres d’alçada d’evacuació (aproximadament planta baixa + 3 pisos)"}]},{"text":"Façana accessible = obertures per accedir a cada planta o forjat ocupat. Vies prioritàries d''entrada: les protegides; després, per un sector diferenciat.","refs":[{"ref":"MAN.SP.000, façana accessible","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"Es considera façana accessible d’un edifici aquella que disposi d’obertures per permetre l’accés dels bombers des de l’exterior a cada planta o forjat ocupat."}]},{"text":"Planta de sortida: màxim 15 m des de l''escala protegida fins a la sortida de l''edifici (excepte sector de risc mínim).","refs":[{"ref":"MAN.SP.000, planta de sortida","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"fins a una sortida de l’edifici no ha de superar els 15 metres"}]},{"text":"Reacció = material; resistència = element. R portant, E integritat, I aïllament. d1 = sense gotes inflamades més de 10 s.","refs":[{"ref":"MAN.SP.000, resistència al foc","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"la funció portant (R) que se li exigeixi, així com la integritat (E) i/o l’aïllament tèrmic (I)"}]},{"text":"Parets no portants EI-t; portes de pas EI2-t-C5; portes d''ascensor E-t. Mur tallafocs = mitgera prolongada per sobre de la coberta. Ventilació natural = flotació.","refs":[{"ref":"MAN.SP.000, portes de pas","law":"MAN.SP.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf","quote":"disposar de mecanisme de tancament automàtic (EI2-t-C5)"}]}]}]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf', null, null, null, null
