insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"L''incendi estructural: repte i evolució constructiva"},{"n":"2","title":"Entorns d''intervenció: habitatges, comerços, indústries, centres singulars i subterranis"},{"n":"3","title":"Denominació de façanes (A, B, C, D)"},{"n":"4","title":"Valoració: estructura, plantes, accessibilitat, columna de fum, propagació i ocupants"},{"n":"5","title":"Maniobres d''extinció: interior, cabals i línies, control de gasos, atac transicional"},{"n":"6","title":"Control de la propagació"},{"n":"7","title":"Recerca i salvament: probabilitat de supervivència i tècniques de progressió"}]'::jsonb, '["§ complexitat MAN.INES.000: «Els incendis estructurals no només es caracteritzen pel seu potencial destructiu, sinó també per la complexitat de l''entorn en què es desenvolupen: espais tancats, compartimentats, sovint amb poca visibilitat, calor extrema i risc d’atrapament o col·lapse.»","§ subterranis MAN.INES.000: «Infraestructures subterrànies (aparcaments, túnels...) En túnels o galeries, cal tenir en compte la direcció de propagació dels fums.»","§ edificis nous MAN.INES.000: «Els més nous, en canvi, poden estar més compartimentats però incloure materials sintètics altament combustibles.»","§ convecció MAN.INES.000: «Propagació per fums calents (convecció) Els gasos calents i fums combustibles generats per l’incendi es mouen de forma convectiva cap a zones superiors, a través de forats, patis, escales i espais verticals.»","§ degoteig MAN.INES.000: «Propagació per degoteig (conducció vertical descendent) Un fenomen menys habitual però molt perillós és la propagació per degoteig de materials inflamats des de pisos superiors i que poden generar focus en les plantes inferiors.»","§ atac transicional MAN.INES.000: «No substitueix l’atac interior, sinó que el prepara i el fa més segur.»","§ paret guia MAN.INES.000: «Paret de referència (paret guia): un dels membres del binomi manté sempre contacte amb una paret o element fix.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Coneixements bàsics: definició i característiques generals","blocks":[{"text":"Un incendi estructural és el que es desenvolupa en una edificació i l''afecta parcialment o totalment. És un dels serveis més exigents per als bombers, no només pel seu potencial destructiu sinó per la complexitat de l''entorn on es produeix.","refs":[{"ref":"MAN.INES.000, definició","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"Definició i característiques generals Un incendi estructural és aquell que es desenvolupa en una edificació i l’afecta parcialment o totalment."}]},{"text":"Aquests incendis es desenvolupen en espais tancats i compartimentats, sovint amb poca visibilitat, calor extrema i risc d''atrapament o de col·lapse. Aquestes condicions són les que justifiquen la valoració sistemàtica, el treball en binomi i les tècniques de progressió segura que es veuen al tema.","refs":[{"ref":"MAN.INES.000, característiques","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"Els incendis estructurals no només es caracteritzen pel seu potencial destructiu, sinó també per la complexitat de l''entorn en què es desenvolupen: espais tancats, compartimentats, sovint amb poca visibilitat, calor extrema i risc d’atrapament o col·lapse."}]}]},{"n":"2","title":"Tipus d''edificis i particularitats estructurals","blocks":[{"text":"Els escenaris d''incendi estructural més freqüents són els habitatges, tant unifamiliars com plurifamiliars. L''antiguitat de l''edifici també compta: els edificis més nous poden estar més compartimentats, però poden incloure materials sintètics altament combustibles.","refs":[{"ref":"MAN.INES.000, habitatges","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"Habitatges unifamiliars o plurifamiliars Són els escenaris més freqüents."},{"ref":"MAN.INES.000, edificis nous","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"Els més nous, en canvi, poden estar més compartimentats però incloure materials sintètics altament combustibles."}]},{"text":"Les infraestructures subterrànies (aparcaments, túnels, galeries) tenen particularitats pròpies: en túnels o galeries cal tenir en compte la direcció de propagació dels fums. Les característiques dels comerços, indústries i centres singulars no són a les fonts revisades; cal consultar el manual MAN.INES.000.","refs":[{"ref":"MAN.INES.000, subterranis","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"Infraestructures subterrànies (aparcaments, túnels...) En túnels o galeries, cal tenir en compte la direcció de propagació dels fums."}]}]},{"n":"3","title":"Valoració inicial: elements d''avaluació i denominació de façanes","blocks":[{"text":"Abans de definir el Pla d''acció cal fer una valoració inicial precisa i sistemàtica que inclogui les 6 cares de l''estructura afectada: el 360º al voltant de l''edifici i, a més, la part superior i la inferior.","refs":[{"ref":"MAN.INES.000, valoració 360º","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"Per això, és important una valoració inicial precisa i sistemàtica abans de definir el Pla d’acció, que ha d''incloure les 6 cares de l’estructura afectada, és a dir, el 360º i la part superior i inferior de l’estructura."}]},{"text":"Per parlar tots el mateix llenguatge, les façanes s''anomenen amb lletres i s''ordenen en sentit horari. La façana A és l''accés principal o la que determini el cap d''intervenció; la façana B és la situada a l''esquerra respecte de la façana A. (Seguint el sentit horari venen després la C i la D; la seva definició detallada no és a les fonts revisades.)","refs":[{"ref":"MAN.INES.000, façana A","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"S’anomenen amb lletres i s’ordenen en sentit horari. - Façana A: l’accés principal o el que determini el cap d’intervenció."},{"ref":"MAN.INES.000, façana B","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"- Façana B: situada a l’esquerra respecte la façana A."}]}]},{"n":"4","title":"Nombre de plantes i accessibilitat","blocks":[{"text":"Com més plantes té l''edifici, més potencial de propagació vertical presenta, especialment si l''incendi és en una planta inferior: tot el que hi ha per sobre queda exposat al fum i a la calor que pugen.","refs":[{"ref":"MAN.INES.000, nombre de plantes","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"Importància del nombre de plantes Quantes més plantes tingui l’edifici, més potencial de propagació vertical presenta, especialment si l’incendi es troba en una planta inferior."}]},{"text":"Pel que fa a l''accés, cal prioritzar la «ruta freda», és a dir, l''accés lliure de fums de l''incendi.","refs":[{"ref":"MAN.INES.000, ruta freda","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"Prioritzar l’accés per la “ruta freda” o lliure de fums de l’incendi."}]}]},{"n":"5","title":"Anàlisi de la columna de fum","blocks":[{"text":"El fum dona informació sobre l''incendi. Un fum molt dens i opac és habitualment senyal d''un gran volum de combustibles en combustió i/o de poca ventilació. Els altres indicadors del fum (color, velocitat, volum) no són a les fonts revisades; cal consultar el manual MAN.INES.000.","refs":[{"ref":"MAN.INES.000, fum dens i opac","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"Fum molt dens i opac: habitualment és senyal d’un gran volum de combustibles en combustió i/o poca ventilació."}]}]},{"n":"6","title":"Mecanismes de propagació","blocks":[{"text":"Propagació per fums calents (convecció): els gasos calents i els fums combustibles es mouen de manera convectiva cap a zones superiors a través de forats, patis, escales i espais verticals.","refs":[{"ref":"MAN.INES.000, convecció","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"Propagació per fums calents (convecció) Els gasos calents i fums combustibles generats per l’incendi es mouen de forma convectiva cap a zones superiors, a través de forats, patis, escales i espais verticals."}]},{"text":"Per escales obertes actua l''efecte xemeneia: els fums pugen ràpidament i fan augmentar la temperatura i els gasos tòxics i reduir la visibilitat als pisos superiors.","refs":[{"ref":"MAN.INES.000, escales obertes","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"Per escales obertes: o L’efecte xemeneia fa que els fums pugin ràpidament, augmentant la temperatura, els gasos tòxics i reduint la visibilitat als pisos superiors."}]},{"text":"Propagació per degoteig (conducció vertical descendent): és menys habitual però molt perillosa. Materials inflamats cauen des de pisos superiors i poden generar nous focus a les plantes inferiors.","refs":[{"ref":"MAN.INES.000, degoteig","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"Propagació per degoteig (conducció vertical descendent) Un fenomen menys habitual però molt perillós és la propagació per degoteig de materials inflamats des de pisos superiors i que poden generar focus en les plantes inferiors."}]}]},{"n":"7","title":"Informació sobre ocupants i evacuació","blocks":[{"text":"Per estimar quanta gent pot haver-hi dins d''una estructura, els dos factors clau són l''ús de l''estructura i l''hora del dia.","refs":[{"ref":"MAN.INES.000, ocupació","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"L’ús de l’estructura i l’hora del dia són dos factors claus per estimar l’ocupació."}]},{"text":"L''ascensor només es pot autoritzar per a l''evacuació si es coneixen les condicions tècniques i l''estat de la instal·lació.","refs":[{"ref":"MAN.INES.000, ascensor","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"Només es pot autoritzar l’ús de l’ascensor en evacuació si es coneixen les condicions tècniques i l’estat de la instal·lació."}]}]},{"n":"8","title":"Extinció interior i control de gasos calents","blocks":[{"text":"La tria de la línia depèn del cabal necessari. Les línies de 25 mm són útils per a maniobres ràpides, amb alta mobilitat i quan el cabal necessari és moderat. Les línies de 45 mm proporcionen més cabal i millor rendiment de refredament: són especialment útils en escenaris amb alta càrrega tèrmica o incendis d''alt potencial i donen més seguretat a les dotacions interiors.","refs":[{"ref":"MAN.INES.000, línies de 25 mm","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"Línies de 25 mm: útils per a maniobres ràpides, amb alta mobilitat i quan el cabal necessari és moderat."},{"ref":"MAN.INES.000, línies de 45 mm","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"Línies de 45 mm: proporcionen més cabal i millor rendiment de refredament, especialment útils en escenaris amb alta càrrega tèrmica o incendis d’alt potencial, aspecte que aporta més seguretat a les dotacions interiors."}]},{"text":"Durant la progressió interior es fan moviments amplis de llança per desplaçar els gasos, en forma d''«O», de «Z» o de «figura de 8», per refredar uniformement i poder avançar. En edificis grans o espais amplis, les pulsacions són una mica més llargues, d''1 a 5 segons.","refs":[{"ref":"MAN.INES.000, moviments de llança","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"Durant el progrés interior s’utilitzen moviments amplis per desplaçar gasos, com és en forma d’ “O”, “Z” o “figura de 8” per refredar uniformement i poder avançar."},{"ref":"MAN.INES.000, pulsacions","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"En edificis grans o espais amplis, la durada de les pulsacions són una mica més llargues (1–5 s)."}]},{"text":"Entre les tècniques d''extinció hi ha el «pintat de parets», que consisteix a refredar les superfícies combustibles (per exemple, en cases de fusta) per limitar-ne la pirolització.","refs":[{"ref":"MAN.INES.000, pintat de parets","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"En les tècniques d''extinció hi ha el \"pintat de parets\" que és el refredament d''aquestes superfícies combustibles (cases de fusta) per limitar la pirolització."}]}]},{"n":"9","title":"Maniobra transicional i control de la propagació","blocks":[{"text":"La maniobra d''atac transicional és un atac ofensiu exterior directe a nivell de terra: s''aplica aigua des de l''exterior abans d''entrar, per reduir la temperatura i l''energia del «motor» de l''incendi. No substitueix l''atac interior, sinó que el prepara i el fa més segur.","refs":[{"ref":"MAN.INES.000, maniobra transicional","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"Maniobra transicional La maniobra d’atac transicional és un atac ofensiu exterior directe a nivell de terra, que consisteix en aplicar aigua des de l’exterior abans d’entrar, amb l’objectiu de reduir la temperatura i l’energia del motor de l’incendi."},{"ref":"MAN.INES.000, maniobra transicional","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"No substitueix l’atac interior, sinó que el prepara i el fa més segur."}]},{"text":"Les maniobres específiques de control de la propagació, la ventilació i el control de subministraments (gas, electricitat) no són a les fonts revisades; cal consultar el manual MAN.INES.000. Les fonts sí que recorden que la propagació aprofita forats, patis, escales i espais verticals, que són, per tant, els punts que cal vigilar.","refs":[{"ref":"MAN.INES.000, convecció","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"a través de forats, patis, escales i espais verticals"}]}]},{"n":"10","title":"Recerca i salvament","blocks":[{"text":"La recerca es prioritza segons la probabilitat de supervivència. Els espais amb mínima probabilitat es consideren no compatibles amb la vida i només es busquen si no hi ha altres opcions o si hi ha indicis clars de presència de víctimes. Els altres nivells de probabilitat no són a les fonts revisades.","refs":[{"ref":"MAN.INES.000, mínima probabilitat","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"Espais amb mínima probabilitat, considerats no compatibles amb la vida (només si no hi ha altres opcions o indicis clars de presència de víctimes)."}]},{"text":"La progressió en rastreig total, amb tres punts de recolzament, s''utilitza quan la visibilitat és nul·la i hi ha acumulació de calor o risc elevat.","refs":[{"ref":"MAN.INES.000, rastreig total","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"Progressió en rastreig total (amb tres punts de recolzament): utilitzat quan la visibilitat és nul·la i hi ha acumulació de calor o risc elevat."}]}]},{"n":"11","title":"Seguretat: treball en binomi i tècniques d''entrada i avanç segur","blocks":[{"text":"El desplaçament es fa sempre en binomi, amb responsabilitat compartida, i seguint punts de referència fixos. Una tècnica bàsica és la paret de referència o paret guia: un dels membres del binomi manté sempre el contacte amb una paret o element fix.","refs":[{"ref":"MAN.INES.000, binomi","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"El desplaçament es fa en binomi, amb responsabilitat compartida, i seguint sempre punts de referència fixos."},{"ref":"MAN.INES.000, paret guia","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"Paret de referència (paret guia): un dels membres del binomi manté sempre contacte amb una paret o element fix."}]},{"text":"Els riscos específics que justifiquen aquestes precaucions són l''atrapament i el col·lapse, en un entorn de poca visibilitat i calor extrema. La zonificació, el control d''accessos i d''ERA i els procediments d''emergència no són a les fonts revisades; cal consultar el manual MAN.INES.000 (i el tema 20 per als ERA).","refs":[{"ref":"MAN.INES.000, característiques","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"sovint amb poca visibilitat, calor extrema i risc d’atrapament o col·lapse"}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Incendi estructural = en una edificació, l''afecta parcialment o totalment. Escenari més freqüent: habitatges.","refs":[{"ref":"MAN.INES.000, habitatges","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"Habitatges unifamiliars o plurifamiliars Són els escenaris més freqüents."}]},{"text":"Valoració: 6 cares (360º + part superior i inferior). Façanes en sentit horari: A = accés principal; B = a l''esquerra de l''A.","refs":[{"ref":"MAN.INES.000, valoració 360º","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"les 6 cares de l’estructura afectada, és a dir, el 360º i la part superior i inferior de l’estructura"}]},{"text":"Més plantes = més propagació vertical (sobretot si el foc és avall). Accés per la ruta freda. Ocupació: ús + hora del dia. Ascensor només si se''n coneix l''estat.","refs":[{"ref":"MAN.INES.000, ocupació","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"L’ús de l’estructura i l’hora del dia són dos factors claus per estimar l’ocupació."}]},{"text":"Fum dens i opac = molt combustible i/o poca ventilació. Escales obertes = efecte xemeneia. Degoteig = propagació descendent.","refs":[{"ref":"MAN.INES.000, fum dens i opac","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"habitualment és senyal d’un gran volum de combustibles en combustió i/o poca ventilació"}]},{"text":"25 mm = mobilitat i cabal moderat; 45 mm = més cabal i seguretat. Moviments en O, Z o 8. Pulsacions d''1-5 s en espais amplis. Pintat de parets = limitar la pirolització.","refs":[{"ref":"MAN.INES.000, línies de 25 mm","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"útils per a maniobres ràpides, amb alta mobilitat i quan el cabal necessari és moderat"}]},{"text":"Transicional = aigua des de fora, a nivell de terra, abans d''entrar; prepara l''atac interior, no el substitueix.","refs":[{"ref":"MAN.INES.000, maniobra transicional","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"No substitueix l’atac interior, sinó que el prepara i el fa més segur."}]},{"text":"Mínima probabilitat = no compatible amb la vida. Rastreig total (3 punts) = visibilitat nul·la. Sempre en binomi i amb paret guia.","refs":[{"ref":"MAN.INES.000, rastreig total","law":"MAN.INES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf","quote":"utilitzat quan la visibilitat és nul·la i hi ha acumulació de calor o risc elevat"}]}]}]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf', null, null, null, null
