insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.SANI.000 Intervenció bàsica en assistència sanitària (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t28-assistencia-sanitaria', 'Tema 28. Intervenció bàsica en assistència sanitària') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t28-assistencia-sanitaria' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"L''assistència sanitària en emergències i el paper dels Bombers"},{"n":"2","title":"Cadena assistencial i contínuum assistencial"},{"n":"3","title":"Terminologia: SVB/SVA, urgència/emergència, signe/símptoma/síndrome, edat, anatomia i postures"},{"n":"4","title":"Tipus d''intervencions sanitàries de Bombers"},{"n":"5","title":"Valoració primària XABCDE: hemorràgia massiva, via aèria, respiració i circulació"},{"n":"6","title":"Constants: FR, SpO₂, pols, FC, ompliment capil·lar i pell"}]'::jsonb, '["§ difícil accés MAN.SANI.000: «Aquesta capacitat de Bombers de poder oferir una assistència sanitària en emergències és especialment rellevant en escenaris amb difícil accés per als serveis mèdics, com ara entorns de muntanya, aquàtics, incendis, accidents de trànsit, incidents amb múltiples afectats o catàstrofes.»","§ contínuum MAN.SANI.000: «L’objectiu és mantenir una continuïtat assistencial (contínuum assistencial) on cada esglaó reforça l’anterior i permet minimitzar el temps de resposta i maximitzar les possibilitats de supervivència i recuperació.»","§ suport vital MAN.SANI.000: «A continuació, es recullen alguns dels termes més rellevants: a) Suport Vital bàsic (SVB) i suport vital avançat (SVA) El suport vital és el conjunt de maniobres i tècniques destinades a mantenir les funcions vitals d’una persona davant d’una situació de risc imminent de mort.»","§ intern/extern MAN.SANI.000: «Intern/extern: més a prop o més lluny de la línia mitjana del cos.»","§ freqüència respiratòria MAN.SANI.000: «La freqüència respiratòria és el nombre de respiracions completes que fa un adult en un minut, i és un indicador essencial de l’efectivitat de la ventilació.»","§ musculatura accessòria MAN.SANI.000: «L’ús de musculatura accessòria (músculs del coll, espatlles i intercostals) i l’aleteig nasal mostra que el pacient fa un esforç extra per respirar, cosa que és un signe de compromís respiratori greu.»","§ saturació MAN.SANI.000: «La saturació d’oxigen mesura el percentatge d’hemoglobina que transporta oxigen a la sang i és un indicador directe de l’eficàcia de l’intercanvi gasós als pulmons.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Marc general: l''assistència sanitària en emergències i el paper dels Bombers","blocks":[{"text":"L''objectiu principal de l''assistència sanitària en emergències és preservar la vida, estabilitzar les funcions vitals i facilitar la transferència segura del pacient fins a l''atenció definitiva.","refs":[{"ref":"MAN.SANI.000, objectiu","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"L’objectiu principal és preservar la vida, estabilitzar les funcions vitals i facilitar la transferència segura del pacient fins a l’atenció definitiva."}]},{"text":"La capacitat dels Bombers d''oferir assistència sanitària és especialment rellevant en escenaris de difícil accés per als serveis mèdics: muntanya, medi aquàtic, incendis, accidents de trànsit, incidents amb múltiples afectats o catàstrofes. La Llei 5/1994 ja inclou el suport sanitari en emergències entre les funcions operatives de l''escala tècnica.","refs":[{"ref":"MAN.SANI.000, paper dels Bombers","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"Aquesta capacitat de Bombers de poder oferir una assistència sanitària en emergències és especialment rellevant en escenaris amb difícil accés per als serveis mèdics, com ara entorns de muntanya, aquàtics, incendis, accidents de trànsit, incidents amb múltiples afectats o catàstrofes."},{"ref":"Art. 16.1.c) L5","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"En la escala técnica, las operativas en tareas de prevención y extinción de incendios y de salvamentos y de apoyo sanitario en emergencias"}]}]},{"n":"2","title":"Cadena assistencial i contínuum assistencial","blocks":[{"text":"La cadena assistencial busca una continuïtat (contínuum assistencial) en què cada esglaó reforça l''anterior, de manera que es minimitza el temps de resposta i es maximitzen les possibilitats de supervivència i recuperació. L''organització concreta del sistema sanitari d''emergències a Catalunya no és a les fonts revisades; cal consultar el manual MAN.SANI.000.","refs":[{"ref":"MAN.SANI.000, contínuum","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"L’objectiu és mantenir una continuïtat assistencial (contínuum assistencial) on cada esglaó reforça l’anterior i permet minimitzar el temps de resposta i maximitzar les possibilitats de supervivència i recuperació."}]}]},{"n":"3","title":"Terminologia bàsica: suport vital, urgència, signe i símptoma","blocks":[{"text":"El suport vital és el conjunt de maniobres i tècniques destinades a mantenir les funcions vitals d''una persona davant una situació de risc imminent de mort. Es distingeix el suport vital bàsic (SVB) del suport vital avançat (SVA). L''objectiu del SVB és mantenir les constants vitals de la víctima per evitar l''aturada cardíaca; si l''aturada es produeix, s''inicia la RCP.","refs":[{"ref":"MAN.SANI.000, suport vital","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"a) Suport Vital bàsic (SVB) i suport vital avançat (SVA) El suport vital és el conjunt de maniobres i tècniques destinades a mantenir les funcions vitals d’una persona davant d’una situació de risc imminent de mort."},{"ref":"MAN.SANI.000, SVB","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"L’objectiu del SVB és mantenir les constants vitals en una víctima per tal d’evitar l’aturada cardíaca, cas en què s’iniciaria la maniobra de RCP."}]},{"text":"Des del punt de vista sanitari, una urgència és la condició que, si no s''atén en 24-48 hores, pot comportar complicacions.","refs":[{"ref":"MAN.SANI.000, urgència","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"Des d’un punt de vista sanitari, és aquella condició que, si no és atesa en 24-48 h, pot comportar complicacions."}]},{"text":"Un signe és una manifestació observable i mesurable (pal·lidesa, febre, hemorràgia). Un símptoma és una sensació subjectiva que expressa la víctima i que no es pot mesurar (dolor, set, mareig).","refs":[{"ref":"MAN.SANI.000, signe","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"Un signe és una manifestació observable i mesurable (ex.: pal·lidesa, febre, hemorràgia)."},{"ref":"MAN.SANI.000, símptoma","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"Un símptoma és una sensació subjectiva que expressa la víctima i no pot ser mesurada (ex.: dolor, set, mareig)."}]}]},{"n":"4","title":"Terminologia anatòmica i postures","blocks":[{"text":"La posició anatòmica estàndard és dret, mirant al front, amb els braços al costat del cos i els palmells cap endavant. És la referència per descriure on és una lesió.","refs":[{"ref":"MAN.SANI.000, posició anatòmica","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"La posició anatòmica estàndard és dret, mirant al front, braços al costat del cos amb els palmells cap endavant."}]},{"text":"Termes de localització: proximal i distal volen dir més a prop o més lluny del tronc (en les extremitats); intern i extern, més a prop o més lluny de la línia mitjana del cos.","refs":[{"ref":"MAN.SANI.000, proximal/distal","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"Proximal/distal: més a prop o més lluny del tronc (en extremitats)."},{"ref":"MAN.SANI.000, intern/extern","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"Intern/extern: més a prop o més lluny de la línia mitjana del cos."}]},{"text":"Postures: en Trendelemburg la persona està estirada en decúbit supí amb el cap més avall que els peus, per afavorir la circulació als òrgans principals.","refs":[{"ref":"MAN.SANI.000, Trendelemburg","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"Trendelemburg: estirat decúbit supí amb el cap més avall que els peus per afavorir la circulació als organs principals."}]}]},{"n":"5","title":"Valoració de la víctima: valoració primària XABCDE","blocks":[{"text":"La valoració primària segueix l''ordre XABCDE. El primer pas (X, eXsanguination) és detectar i controlar immediatament una hemorràgia massiva, perquè la pèrdua ràpida de sang pot causar la mort en minuts, fins i tot abans que un problema de via aèria.","refs":[{"ref":"MAN.SANI.000, hemorràgia massiva","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"Hemorràgia massiva (eXsanguination) La detecció i control immediat d’una hemorràgia massiva és el primer pas de la valoració primària, ja que la pèrdua ràpida de sang pot provocar la mort en qüestió de minuts, fins i tot abans que un problema de via aèria."}]},{"text":"El segon pas (A, Airway) és la via aèria, perquè el seu bloqueig pot provocar una hipòxia ràpida i la mort en pocs minuts. Després venen la respiració (B) i la circulació (C). La primera impressió, la valoració secundària, els passos D i E i la identificació del TCE no són a les fonts revisades; cal consultar el manual MAN.SANI.000.","refs":[{"ref":"MAN.SANI.000, via aèria","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"Via aèria (Airway) La via aèria és el segon pas de la valoració, ja que el seu bloqueig pot provocar una hipòxia ràpida i mort en pocs minuts."}]}]},{"n":"6","title":"Respiració: freqüència, esforç, simetria i saturació","blocks":[{"text":"La freqüència respiratòria (FR) és el nombre de respiracions completes que fa un adult en un minut i és un indicador essencial de l''efectivitat de la ventilació. Encara que cal conèixer els valors normals, és una FR superior a 30 rpm la que exigeix una actuació immediata.","refs":[{"ref":"MAN.SANI.000, FR","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"La freqüència respiratòria és el nombre de respiracions completes que fa un adult en un minut, i és un indicador essencial de l’efectivitat de la ventilació."},{"ref":"MAN.SANI.000, FR > 30","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"Per aquest motiu, tot i que conèixer els valors normals és important, és la FR > 30 rpm la que requereix una actuació immediata."}]},{"text":"L''ús de la musculatura accessòria (músculs del coll, espatlles i intercostals) i l''aleteig nasal indiquen que el pacient fa un esforç extra per respirar: és signe de compromís respiratori greu. La respiració paradoxal és una respiració descompensada en què, en la inspiració, l''abdomen es deprimeix i, en l''expiració, s''expandeix: el diafragma no té capacitat de contraure''s.","refs":[{"ref":"MAN.SANI.000, musculatura accessòria","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"L’ús de musculatura accessòria (músculs del coll, espatlles i intercostals) i l’aleteig nasal mostra que el pacient fa un esforç extra per respirar, cosa que és un signe de compromís respiratori greu."},{"ref":"MAN.SANI.000, respiració paradoxal","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"Per altra banda, la respiració paradoxal, és aquell tipus de respiració descompensada en què en la inspiració l''abdomen es deprimeix i en l''expiració s''expandeix, signe que el diafragma no té la capacitat de contraure''s."}]},{"text":"També cal comprovar la simetria: si un costat del tòrax es mou menys que l''altre, pot indicar pneumotòrax, fractures de costelles o alteracions pulmonars.","refs":[{"ref":"MAN.SANI.000, simetria","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"També és important comprovar la simetria: si un costat del tòrax es mou menys que l’altre, pot suggerir pneumotòrax, fractures de costelles o alteracions pulmonars."}]},{"text":"La saturació d''oxigen (SpO₂) mesura el percentatge d''hemoglobina que transporta oxigen a la sang i és un indicador directe de l''eficàcia de l''intercanvi gasós als pulmons. Valors: 95-100 % normalitat; 90-94 % hipòxia lleu; per sota del 90 % hipòxia greu.","refs":[{"ref":"MAN.SANI.000, SpO2","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"La saturació d’oxigen mesura el percentatge d’hemoglobina que transporta oxigen a la sang i és un indicador directe de l’eficàcia de l’intercanvi gasós als pulmons."},{"ref":"MAN.SANI.000, valors SpO2","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"Saturació d’oxigen (SpO₂) Valors dins la normalitat 95-100 % Hipòxia lleu 90-94 % Hipòxia greu < 90 %"}]}]},{"n":"7","title":"Circulació: pols, freqüència cardíaca i perfusió","blocks":[{"text":"El pols radial es palpa al canell, a la cara lateral del radi, i serveix per valorar el flux sanguini perifèric. El pols carotidi, al costat de la tràquea, al coll, és un pols central que es manté fins i tot amb una pressió arterial molt baixa (60 mmHg); per això s''utilitza quan el radial no es palpa o en casos de compromís vital. S''ha de palpar sempre només un costat del coll, per no comprometre el flux sanguini cerebral.","refs":[{"ref":"MAN.SANI.000, pols radial","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"El pols radial es palpa al canell, a la cara lateral del radi, i és útil per valorar el flux sanguini perifèric."},{"ref":"MAN.SANI.000, pols carotidi","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"El pols carotidi, situat al costat de la tràquea, al coll, és un pols central i es manté fins i tot en situacions de pressió arterial molt baixa (60 mmHg); per això s’utilitza quan el pols radial no és palpable o en casos de compromís vital."},{"ref":"MAN.SANI.000, un sol costat","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"Cal palpar sempre un sol costat del coll per evitar comprometre el flux sanguini cerebral."}]},{"text":"Freqüència cardíaca (FC): 60-100 bpm és normalitat; més de 100 bpm, taquicàrdia; menys de 60 bpm, bradicàrdia.","refs":[{"ref":"MAN.SANI.000, FC","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"Freqüència cardíaca (FC) Valors dins la normalitat 60-100 bpm Taquicàrdia > 100 bpm Bradicàrdia < 60 bpm"}]},{"text":"La prova de l''ompliment capil·lar consisteix a pressionar la punta d''un dit o l''ungla fins que la pell es torna pàl·lida i després alliberar-la. Una perfusió reduïda és habitual en situacions d''hipovolèmia, xoc, hipotensió o hipotèrmia.","refs":[{"ref":"MAN.SANI.000, ompliment capil·lar","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"Consisteix a pressionar la punta d’un dit o l’ungla fins que la pell es torna pàl·lida, i després alliberar-la."},{"ref":"MAN.SANI.000, perfusió","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"Una perfusió reduïda és habitual en situacions d’hipovolèmia, xoc, hipotensió o hipotèrmia."}]}]},{"n":"8","title":"Maniobres bàsiques d''assistència sanitària","blocks":[{"text":"De les maniobres de l''epígraf, les fonts revisades només recullen el criteri de prioritat: l''hemorràgia massiva es controla de manera immediata, abans fins i tot que la via aèria, i la RCP s''inicia quan el SVB no ha pogut evitar l''aturada cardíaca. Les tècniques de control d''hemorràgies, via aèria, OVACE, ventilació i oxigenoteràpia, RCP amb i sense DEA, posició lateral de seguretat, tractament de lesions, mobilització, immobilització i transport no són a les fonts revisades; cal consultar el manual MAN.SANI.000.","refs":[{"ref":"MAN.SANI.000, SVB","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"per tal d’evitar l’aturada cardíaca, cas en què s’iniciaria la maniobra de RCP"},{"ref":"MAN.SANI.000, hemorràgia massiva","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"La detecció i control immediat d’una hemorràgia massiva és el primer pas de la valoració primària"}]}]},{"n":"9","title":"Seguretat en l''assistència sanitària","blocks":[{"text":"L''autoprotecció, la protecció de la víctima, l''organització de l''escenari, el risc biològic i la comunicació operativa no són a les fonts revisades; cal consultar el manual MAN.SANI.000. Les fonts sí que destaquen que l''assistència dels Bombers es fa sovint en escenaris de difícil accés i perillosos (incendis, accidents de trànsit, medi aquàtic), on la seguretat de l''escena condiciona l''atenció.","refs":[{"ref":"MAN.SANI.000, paper dels Bombers","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"escenaris amb difícil accés per als serveis mèdics, com ara entorns de muntanya, aquàtics, incendis, accidents de trànsit, incidents amb múltiples afectats o catàstrofes"}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Objectiu: preservar la vida, estabilitzar i transferir amb seguretat. Contínuum assistencial: cada esglaó reforça l''anterior.","refs":[{"ref":"MAN.SANI.000, objectiu","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"preservar la vida, estabilitzar les funcions vitals i facilitar la transferència segura del pacient fins a l’atenció definitiva"}]},{"text":"Signe = observable i mesurable; símptoma = subjectiu (dolor, set, mareig). Urgència = complicacions si no s''atén en 24-48 h. SVB = evitar l''aturada; si n''hi ha, RCP.","refs":[{"ref":"MAN.SANI.000, urgència","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"si no és atesa en 24-48 h, pot comportar complicacions"}]},{"text":"Posició anatòmica: dret, de cara, palmells endavant. Proximal/distal = tronc; intern/extern = línia mitjana. Trendelemburg = decúbit supí, cap més avall que els peus.","refs":[{"ref":"MAN.SANI.000, Trendelemburg","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"estirat decúbit supí amb el cap més avall que els peus"}]},{"text":"XABCDE: X hemorràgia massiva (1r), A via aèria (2n), B respiració, C circulació.","refs":[{"ref":"MAN.SANI.000, via aèria","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"La via aèria és el segon pas de la valoració"}]},{"text":"FR > 30 rpm = actuació immediata. Paradoxal: abdomen es deprimeix en inspirar. Asimetria toràcica: pneumotòrax, fractures de costelles.","refs":[{"ref":"MAN.SANI.000, FR > 30","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"és la FR > 30 rpm la que requereix una actuació immediata"}]},{"text":"SpO₂ 95-100 % normal, 90-94 % hipòxia lleu, < 90 % greu. FC 60-100 normal, > 100 taquicàrdia, < 60 bradicàrdia.","refs":[{"ref":"MAN.SANI.000, FC","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"Taquicàrdia > 100 bpm Bradicàrdia < 60 bpm"}]},{"text":"Radial: canell, cara lateral del radi. Carotidi: central, es manté a 60 mmHg; un sol costat. Perfusió reduïda: hipovolèmia, xoc, hipotensió, hipotèrmia.","refs":[{"ref":"MAN.SANI.000, pols carotidi","law":"MAN.SANI.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf","quote":"es manté fins i tot en situacions de pressió arterial molt baixa (60 mmHg)"}]}]}]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf', null, null, null, null
