insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.SVES.000 Intervenció bàsica en estructures col·lapsades (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t30-estructures-collapsades', 'Tema 30. Intervenció bàsica en estructures col·lapsades') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t30-estructures-collapsades' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Objectiu i marc: equips USAR, INSARAG, OSOCC i GREC"},{"n":"2","title":"Valoració del col·lapse estructural"},{"n":"3","title":"Tipus de col·lapse: total, parcial i secundari"},{"n":"4","title":"Recerca física: valoració inicial i crida i escolta"},{"n":"5","title":"Recerca instrumentalitzada i canina"},{"n":"6","title":"Apuntalaments: verticals, horitzontals i inclinats"},{"n":"7","title":"Senyalització de zones i de víctimes"}]'::jsonb, '["§ objectiu MAN.SVES.000: «L’objectiu principal és dotar els intervinents amb coneixements tècnics i pràctics bàsics que permetin actuar amb seguretat, eficiència i coordinació en escenaris complexos com ara ensorraments d’edificis, esllavissades o col·lapses estructurals derivats d’incendis, explosions o fenòmens naturals.»","§ INSARAG local MAN.SVES.000: «Els principis INSARAG són d’aplicació també a escala nacional i regional per millorar la coordinació entre bombers, protecció civil i serveis mèdics.»","§ col·lapse parcial MAN.SVES.000: «Col·lapses parcials Un col·lapse parcial es produeix quan només una part de l’estructura cedeix, ja sigui un mur, una coberta, un forjat o qualsevol altre element constructiu, mentre la resta de l’edificació roman aparentment estable.»","§ valoració inicial MAN.SVES.000: «Aquest procés ha de ser sistemàtic, progressiu i sempre subordinat a la seguretat dels intervinents.»","§ recerca canina MAN.SVES.000: «Canina La recerca canina és una maniobra de localització de víctimes atrapades que es basa en l’olfacte d’alt rendiment dels gossos ensinistrats, que treballen seguint l’olor humana emesa des de sota la runa o altres estructures col·lapsades.»","§ apuntalaments horitzontals MAN.SVES.000: «Apuntalaments horitzontals Els apuntalaments horitzontals són estructures provisionals dissenyades per estampar o sostenir murs que han perdut part de la seva resistència estructural des de l’exterior o assegurar parets de contenció i excavacions des de l’interior.»","§ senyalització MAN.SVES.000: «Senyalització La correcta senyalització de les zones en un escenari d’estructura col·lapsada és essencial per garantir la seguretat, l’eficàcia i la coordinació dels equips de rescat.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Introducció i objectiu del tema","blocks":[{"text":"El manual vol donar als intervinents els coneixements tècnics i pràctics bàsics per actuar amb seguretat, eficiència i coordinació en escenaris complexos: ensorraments d''edificis, esllavissades o col·lapses estructurals derivats d''incendis, explosions o fenòmens naturals. Seguretat, eficiència i coordinació són, doncs, les tres idees que travessen tot el tema.","refs":[{"ref":"MAN.SVES.000, § objectiu","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"L’objectiu principal és dotar els intervinents amb coneixements tècnics i pràctics bàsics que permetin actuar amb seguretat, eficiència i coordinació en escenaris complexos com ara ensorraments d’edificis, esllavissades o col·lapses estructurals derivats d’incendis, explosions o fenòmens naturals."}]}]},{"n":"2","title":"Evolució històrica i marc internacional: INSARAG i OSOCC","blocks":[{"text":"INSARAG (International Search and Rescue Advisory Group) és una xarxa de Nacions Unides que coordina la resposta internacional en situacions d''ensorraments greus, sobretot en catàstrofes naturals com els terratrèmols. Sobre el terreny, els equips internacionals es coordinen a través del sistema OSOCC (On-Site Operations Coordination Centre), liderat per Nacions Unides.","refs":[{"ref":"MAN.SVES.000, § INSARAG","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"INSARAG: marc internacional de recerca i rescat INSARAG (International Search and Rescue Advisory Group) és una xarxa de Nacions Unides que coordina la resposta internacional en situacions d’ensorraments greus, especialment en escenaris de catàstrofes naturals com els terratrèmols."},{"ref":"MAN.SVES.000, § OSOCC","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Es coordinen a través del sistema OSOCC (On-Site Operations Coordination Centre) liderat per Nacions Unides."}]},{"text":"L''exemple històric que recull el manual és el terratrèmol d''Haití (2010): més de 40 equips USAR de diferents països hi van treballar conjuntament, coordinats sota el sistema INSARAG, van salvar centenars de vides i van compartir informació tècnica en temps real. Els principis INSARAG també s''apliquen a escala nacional i regional per millorar la coordinació entre bombers, protecció civil i serveis mèdics. La resta de l''evolució històrica de les operacions de rescat en terratrèmols no és als extractes revisats; cal consultar el manual MAN.SVES.000.","refs":[{"ref":"MAN.SVES.000, § Haití","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Després del terratrèmol d’Haití (2010), més de 40 equips USAR de diferents països van treballar de manera conjunta, coordinats sota el sistema INSARAG, salvant centenars de vides i compartint informació tècnica en temps real."},{"ref":"MAN.SVES.000, § INSARAG local","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Els principis INSARAG són d’aplicació també a escala nacional i regional per millorar la coordinació entre bombers, protecció civil i serveis mèdics."}]}]},{"n":"3","title":"Equips especialitzats: unitats USAR i GREC","blocks":[{"text":"Els equips USAR (Urban Search and Rescue) són dispositius especialitzats en recerca i rescat en entorns urbans col·lapsats. Al Cos de Bombers de la Generalitat sempre hi ha hagut experts en valoració d''estructures, però el Grup de Recolzament en Estructures Col·lapsades (GREC) no es va constituir oficialment fins al 2021, com a subàmbit de la guàrdia de suport.","refs":[{"ref":"MAN.SVES.000, § USAR","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Equips USAR (Urban Search and Rescue) Els equips USAR són dispositius especialitzats en actuacions de recerca i rescat en entorns urbans col·lapsats."},{"ref":"MAN.SVES.000, § GREC","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"El Grup de Recolzament en Estructures Col·lapsades (GREC) Tot i que el Cos de Bombers de la Generalitat de Catalunya sempre ha tingut experts en valoració d’estructures, no va ser fins el 2021 que es va constituir oficialment el Grup de recolzament en estructures col·lapsades (GREC) com un subàmbit de la guàrdia de suport."}]}]},{"n":"4","title":"Valoració inicial del col·lapse estructural","blocks":[{"text":"Un col·lapse estructural és la fallida, sobtada o progressiva, d''una construcció quan algun element estructural (forjats, murs, pilars o cobertes) supera el seu límit resistent o elàstic i deixa de complir la funció portadora. La valoració ha de ser sistemàtica, progressiva i sempre subordinada a la seguretat dels intervinents.","refs":[{"ref":"MAN.SVES.000, § col·lapse estructural","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Valoració del col·lapse estructural Un col·lapse estructural és la fallida sobtada o progressiva d’una construcció quan algun dels seus elements estructurals –com ara forjats, murs, pilars o cobertes– supera el seu límit resistent o elàstic, deixant de complir la seva funció portadora."},{"ref":"MAN.SVES.000, § valoració inicial","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Aquest procés ha de ser sistemàtic, progressiu i sempre subordinat a la seguretat dels intervinents."}]}]},{"n":"5","title":"Tipus de col·lapse i riscos associats","blocks":[{"text":"Hi ha col·lapse parcial quan només cedeix una part de l''estructura (un mur, una coberta, un forjat o un altre element) mentre la resta de l''edifici sembla estable. És molt freqüent i pot passar desapercebut en una primera valoració, i per això és especialment perillós per a l''equip intervinent. La descripció del col·lapse total no és als extractes revisats; cal consultar el manual.","refs":[{"ref":"MAN.SVES.000, § col·lapse parcial","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Col·lapses parcials Un col·lapse parcial es produeix quan només una part de l’estructura cedeix, ja sigui un mur, una coberta, un forjat o qualsevol altre element constructiu, mentre la resta de l’edificació roman aparentment estable."},{"ref":"MAN.SVES.000, § perill del parcial","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Aquest tipus de col·lapse és molt freqüent i pot passar desapercebut en una primera valoració, fet que el converteix en especialment perillós per a l’equip intervinent."}]},{"text":"El col·lapse secundari és el que es produeix després d''un primer col·lapse, com a conseqüència directa de la inestabilitat de l''estructura que queda. Cal vigilar molt de prop els signes premonitoris: caiguda de pols, sorolls secs, moviments de runa o canvis en les esquerdes.","refs":[{"ref":"MAN.SVES.000, § col·lapse secundari","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Col·lapses secundaris El col·lapse secundari és aquell que es produeix després d’un primer col·lapse, com a conseqüència directa de la inestabilitat generada a l’estructura restant."},{"ref":"MAN.SVES.000, § signes premonitoris","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Els signes premonitoris –com la caiguda de pols, sorolls secs, moviments de runa, o canvis en les esquerdes– són indicadors que cal vigilar molt de prop."}]}]},{"n":"6","title":"Recerca física","blocks":[{"text":"La recerca física és la primera fase operativa per localitzar víctimes atrapades després d''un col·lapse. Una maniobra típica és la crida i escolta: s''atura completament l''activitat a la zona, es fa silenci absolut i s''emet una crida clara adreçada a les possibles víctimes sota la runa per detectar qualsevol resposta sonora (veus, cops o sorolls).","refs":[{"ref":"MAN.SVES.000, § recerca física","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"La recerca física és la primera fase operativa en la localització de víctimes atrapades després d’un col·lapse."},{"ref":"MAN.SVES.000, § crida i escolta","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Consisteix a aturar completament l’activitat a la zona afectada, fer silenci absolut i emetre una crida clara dirigida a les possibles víctimes atrapades sota la runa per tal de detectar qualsevol resposta sonora: veus, cops o sorolls."}]}]},{"n":"7","title":"Recerca instrumentalitzada i recerca canina","blocks":[{"text":"La recerca instrumentalitzada fa servir aparells. Els geòfons detecten vibracions o sorolls provocats per les víctimes, com cops o moviments. Les càmeres s''introdueixen per forats a la runa o entre esquerdes per localitzar visualment les persones atrapades i valorar-ne la posició i l''estat.","refs":[{"ref":"MAN.SVES.000, § geòfons","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Els geòfons són dispositius que detecten vibracions o sorolls provocats per les víctimes, com ara cops o moviments."},{"ref":"MAN.SVES.000, § càmeres","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Les càmeres s’introdueixen a través de forats a la runa o entre esquerdes per localitzar visualment persones atrapades i valorar-ne la posició i l’estat."}]},{"text":"La recerca canina es basa en l''olfacte d''alt rendiment de gossos ensinistrats, que segueixen l''olor humana que surt de sota la runa o d''altres estructures col·lapsades. El venteig és la maniobra pròpia del gos: rastreja l''aire buscant partícules d''olor corporal.","refs":[{"ref":"MAN.SVES.000, § recerca canina","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Canina La recerca canina és una maniobra de localització de víctimes atrapades que es basa en l’olfacte d’alt rendiment dels gossos ensinistrats, que treballen seguint l’olor humana emesa des de sota la runa o altres estructures col·lapsades."},{"ref":"MAN.SVES.000, § venteig","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Venteig El venteig és el nom que rep la maniobra pròpia del gos, en què rastreja l’aire en la recerca de partícules d’olor corporal."}]}]},{"n":"8","title":"Fonaments dels apuntalaments","blocks":[{"text":"Els apuntalaments són estructures provisionals que permeten assegurar elements inestables en una construcció col·lapsada o malmesa; són una mesura de seguretat i d''estabilització. Els verticals són els més habituals i els més utilitzats pels bombers en col·lapses estructurals.","refs":[{"ref":"MAN.SVES.000, § apuntalaments","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Apuntalaments Els apuntalaments són estructures provisionals que permeten assegurar elements inestables en una construcció col·lapsada o malmesa."},{"ref":"MAN.SVES.000, § verticals","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Apuntalaments verticals Els apuntalaments verticals són els més habituals i utilitzats en les intervencions dels bombers en col·lapses estructurals."}]},{"text":"Els apuntalaments horitzontals serveixen per estampar o sostenir des de l''exterior murs que han perdut resistència, o per assegurar des de l''interior parets de contenció i excavacions. Quan hi ha persones atrapades dins d''una rasa, és habitual fer apuntalaments horitzontals successius a mesura que s''aprofundeix el desenrunament. En els apuntalaments inclinats, les tornapuntes són els elements oblics que fan de puntal inclinat.","refs":[{"ref":"MAN.SVES.000, § horitzontals","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Apuntalaments horitzontals Els apuntalaments horitzontals són estructures provisionals dissenyades per estampar o sostenir murs que han perdut part de la seva resistència estructural des de l’exterior o assegurar parets de contenció i excavacions des de l’interior."},{"ref":"MAN.SVES.000, § rasa","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"En intervencions on hi ha persones atrapades dins d’una rasa, és habitual fer apuntalaments horitzontals successius a mesura que s’aprofundeix el desenrunament."},{"ref":"MAN.SVES.000, § tornapuntes","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Tornapuntes: són els elements oblics que fan la funció de puntal inclinat."}]}]},{"n":"9","title":"Sistemes de senyalització operativa","blocks":[{"text":"Senyalitzar bé les zones és essencial per a la seguretat, l''eficàcia i la coordinació dels equips. Els colors habituals són el vermell per indicar perill i el verd per assenyalar rutes transitables, i la X prohibeix el pas. Quan es detecta una víctima (de manera visual, auditiva o amb eines tècniques), el punt es marca amb una gran V d''uns 50 cm pintada sobre la runa o l''estructura visible.","refs":[{"ref":"MAN.SVES.000, § senyalització","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Senyalització La correcta senyalització de les zones en un escenari d’estructura col·lapsada és essencial per garantir la seguretat, l’eficàcia i la coordinació dels equips de rescat."},{"ref":"MAN.SVES.000, § colors","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Els colors habituals són el vermell per indicar perill, el verd per assenyalar rutes transitables i la X per prohibir el pas."},{"ref":"MAN.SVES.000, § senyalització de víctimes","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Senyalització de víctimes Quan es detecta una víctima —ja sigui de forma visual, auditiva o mitjançant eines tècniques— cal marcar el punt amb una gran V d’uns 50 cm de mida, pintada sobre la runa o estructura visible."}]}]},{"n":"10","title":"Mesures de seguretat","blocks":[{"text":"Tota l''actuació queda subordinada a la seguretat dels intervinents, i la vigilància dels signes premonitoris de col·lapse secundari n''és una peça central. Pel que fa a l''ús d''EPI, la norma general defineix l''equip de protecció individual com qualsevol equip que el treballador porta o subjecta perquè el protegeixi de riscos per a la seva seguretat o salut. L''emplaçament de vehicles, la protecció de la població afectada, el protocol LACES i la comunicació operativa en aquest escenari no són als extractes revisats; cal consultar el manual MAN.SVES.000.","refs":[{"ref":"MAN.SVES.000, § valoració inicial","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Aquest procés ha de ser sistemàtic, progressiu i sempre subordinat a la seguretat dels intervinents."},{"ref":"Art. 2.1 RD 773/1997","law":"RD 773/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-12735","quote":"cualquier equipo destinado a ser llevado o sujetado por el trabajador para que le proteja de uno o varios riesgos que puedan amenazar su seguridad o su salud"}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Col·lapse estructural: fallida sobtada o progressiva quan un element supera el límit resistent o elàstic i deixa de ser portador.","refs":[{"ref":"MAN.SVES.000, § col·lapse estructural","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"supera el seu límit resistent o elàstic, deixant de complir la seva funció portadora."}]},{"text":"INSARAG = xarxa de Nacions Unides; OSOCC = centre de coordinació sobre el terreny. Haití 2010: més de 40 equips USAR.","refs":[{"ref":"MAN.SVES.000, § Haití","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Després del terratrèmol d’Haití (2010), més de 40 equips USAR de diferents països van treballar de manera conjunta"}]},{"text":"GREC: constituït oficialment el 2021 com a subàmbit de la guàrdia de suport.","refs":[{"ref":"MAN.SVES.000, § GREC","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"no va ser fins el 2021 que es va constituir oficialment el Grup de recolzament en estructures col·lapsades (GREC) com un subàmbit de la guàrdia de suport."}]},{"text":"Col·lapse parcial: molt freqüent i pot passar desapercebut. Secundari: després del primer; signes premonitoris = pols, sorolls secs, moviments de runa, canvis en esquerdes.","refs":[{"ref":"MAN.SVES.000, § signes premonitoris","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Els signes premonitoris –com la caiguda de pols, sorolls secs, moviments de runa, o canvis en les esquerdes– són indicadors que cal vigilar molt de prop."}]},{"text":"Recerca física = primera fase (crida i escolta). Geòfons: vibracions i sorolls. Càmeres: per forats i esquerdes. Venteig: el gos rastreja l''aire.","refs":[{"ref":"MAN.SVES.000, § recerca física","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"La recerca física és la primera fase operativa en la localització de víctimes atrapades després d’un col·lapse."}]},{"text":"Apuntalaments verticals = els més habituals. Horitzontals successius a les rases. Tornapuntes = elements oblics del puntal inclinat.","refs":[{"ref":"MAN.SVES.000, § tornapuntes","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Tornapuntes: són els elements oblics que fan la funció de puntal inclinat."}]},{"text":"Senyals: vermell = perill; verd = ruta transitable; X = pas prohibit; V d''uns 50 cm = víctima detectada.","refs":[{"ref":"MAN.SVES.000, § colors","law":"MAN.SVES.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf","quote":"Els colors habituals són el vermell per indicar perill, el verd per assenyalar rutes transitables i la X per prohibir el pas."}]}]}]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf', null, null, null, null
