 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.SVVH.000 Intervenció bàsica en accidents de mobilitat viària (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t32-accidents-mobilitat-viaria', 'Tema 32. Intervenció bàsica en accidents de mobilitat viària') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t32-accidents-mobilitat-viaria' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Context de l''accidentalitat i concepte d''accident de mobilitat"},{"n":"2","title":"Parts dels vehicles i moviments: longitudinal, balanceig i capcineig"},{"n":"3","title":"Seguretat primària, secundària i terciària"},{"n":"4","title":"Autobusos i autocars; camions i vehicles pesants"},{"n":"5","title":"Accidents ferroviaris: tipus de trens, accés i riscos"},{"n":"6","title":"Valoració, posicions dels vehicles i tipus d''atrapament"},{"n":"7","title":"Biomecànica: energia de l''impacte i criteris d''alta energia"},{"n":"8","title":"Plans d''extracció (pla A, pla B, alliberament immediat)"}]'::jsonb, '["§ propulsió no convencional MAN.SVVH.000: «Aquesta realitat fa que els serveis d’emergència, especialment el Cos de Bombers, s’enfrontin a una tipologia d’accidents cada cop més variada i complexa, que pot implicar tant persones com mercaderies, amb risc afegit en cas de vehicles que transportin substàncies perilloses o utilitzin sistemes de propulsió no convencionals (com gas, electricitat o hidrogen).»","§ desplaçament longitudinal MAN.SVVH.000: «Desplaçament longitudinal És el moviment horitzontal endavant i endarrere en el sentit de la marxa.»","§ superestructura MAN.SVVH.000: «La superestructura és la part superior, on s’ubica l’habitacle de passatgers.»","§ tracció elèctrica MAN.SVVH.000: «Encara que el comboi sinistrat sembli aturat i la zona aparentment segura, cal obtenir confirmació oficial que la circulació ha estat tallada i que el sistema de tracció elèctrica està desconnectat.»","§ valoració MAN.SVVH.000: «Valoració La valoració és la fase prèvia i inicial de qualsevol intervenció en accidents de mobilitat.»","§ biomecànica MAN.SVVH.000: «Biomecànica de l’accident de trànsit La biomecànica de l’accident de trànsit és la ciència que, basant-se en la física i la medicina, estudia els mecanismes lesius d’un accident.»","§ pla B MAN.SVVH.000: «És l’opció prevista en paral·lel al Pla A, i es posa en marxa en cas que es produeixi un agreujament sobtat de l’estat de la víctima o una situació sobrevinguda que obligui a reduir el temps d’extracció de la persona afectada.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Context de la mobilitat viària i concepte d''accident","blocks":[{"text":"Un accident de mobilitat és qualsevol incident amb un o més vehicles, en moviment o aturats, que causa danys materials (vehicles, infraestructures, càrregues), ambientals (vessaments, incendis, contaminació) i/o personals (ferits lleus, greus o víctimes mortals) i que requereix una resposta dels serveis d''emergència.","refs":[{"ref":"MAN.SVVH.000, § concepte","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"Els accidents de mobilitat viària Entenem per accident de mobilitat qualsevol incident que implica un o més vehicles en moviment o aturats, que causa danys materials (vehicles, infraestructures, càrregues), ambientals (vessaments, incendis, contaminació) i/o personals (ferits lleus, greus o víctimes mortals) i que requereix una resposta dels serveis d’emergència."}]},{"text":"Les dades d''accidentalitat que recull el manual: l''any amb més accidents de la dècada va ser el 2019, amb més de 24.000 accidents amb víctimes, i el 2023 es va tancar amb 23.591, una xifra lleugerament superior a la mitjana de la dècada. Els bombers s''enfronten a accidents cada vegada més variats i complexos, amb persones i mercaderies, i amb risc afegit quan hi ha vehicles que transporten substàncies perilloses o que fan servir sistemes de propulsió no convencionals (gas, electricitat o hidrogen).","refs":[{"ref":"MAN.SVVH.000, § accidentalitat","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"L’any amb més accidentalitat va ser el 2019, superant els 24.000 accidents amb víctimes, mentre que el 2023 va tancar amb 23.591 accidents, una xifra lleugerament superior a la mitjana de la dècada."},{"ref":"MAN.SVVH.000, § propulsió no convencional","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"Aquesta realitat fa que els serveis d’emergència, especialment el Cos de Bombers, s’enfrontin a una tipologia d’accidents cada cop més variada i complexa, que pot implicar tant persones com mercaderies, amb risc afegit en cas de vehicles que transportin substàncies perilloses o utilitzin sistemes de propulsió no convencionals (com gas, electricitat o hidrogen)."}]}]},{"n":"2","title":"Parts principals del vehicle","blocks":[{"text":"En els vehicles com l''autobús es distingeixen dues parts: el bastidor, que és l''esquelet inferior on s''integren els sistemes mecànics (motor, suspensió i transmissió), i la superestructura, que és la part superior, on hi ha l''habitacle dels passatgers.","refs":[{"ref":"MAN.SVVH.000, § bastidor","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"El bastidor és l’esquelet inferior del vehicle, on s’integren els sistemes mecànics com el motor, la suspensió i la transmissió."},{"ref":"MAN.SVVH.000, § superestructura","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"La superestructura és la part superior, on s’ubica l’habitacle de passatgers."}]}]},{"n":"3","title":"Sistemes de propulsió i de seguretat","blocks":[{"text":"Els sistemes de propulsió no convencionals (gas, electricitat o hidrogen) són un risc afegit en la intervenció; el detall de cada sistema no és als extractes revisats. Pel que fa a la seguretat del vehicle, la seguretat terciària és la que actua després de l''accident: són els sistemes que faciliten una resposta ràpida i eficaç dels serveis d''emergència i les mesures per evitar danys addicionals. La descripció de la seguretat primària i secundària no és a les fonts revisades; cal consultar el manual MAN.SVVH.000.","refs":[{"ref":"MAN.SVVH.000, § seguretat terciària","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"Seguretat terciària La seguretat terciària actua després de l’accident, i fa referència als sistemes que faciliten una resposta ràpida i eficaç per part dels serveis d’emergència, així com a les mesures per evitar danys addicionals."}]}]},{"n":"4","title":"Comportament dinàmic: moviments del vehicle","blocks":[{"text":"Per estabilitzar un vehicle cal conèixer-ne els moviments possibles. El desplaçament longitudinal és el moviment horitzontal endavant i endarrere en el sentit de la marxa. El balanceig és un moviment pivotant a dreta i esquerra sense desplaçament longitudinal. El capcineig és un moviment pivotant endavant i endarrere, també sense desplaçament longitudinal.","refs":[{"ref":"MAN.SVVH.000, § desplaçament longitudinal","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"Desplaçament longitudinal És el moviment horitzontal endavant i endarrere en el sentit de la marxa."},{"ref":"MAN.SVVH.000, § balanceig","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"Balanceig És un moviment pivotant a dreta i esquerra sense desplaçament longitudinal."},{"ref":"MAN.SVVH.000, § capcineig","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"Capcineig És un moviment pivotant endavant i endarrere sense desplaçament longitudinal."}]}]},{"n":"5","title":"Autobusos, autocars, camions i vehicles pesants","blocks":[{"text":"Els autocars estan pensats per a recorreguts mitjans o llargs i prioritzen la comoditat i la seguretat dels passatgers, que hi viatgen sempre asseguts. La normativa fixa uns límits generals per a autobusos i autocars: alçada màxima de 4 metres, amplada de fins a 2,55 metres (2,60 m en casos especials) i longitud d''entre 13,5 i 18,75 metres, segons el nombre d''eixos o si és articulat.","refs":[{"ref":"MAN.SVVH.000, § autocars","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"Autocars: estan concebuts per a recorreguts mitjans o llargs, i prioritzen la comoditat i seguretat dels passatgers, que sempre viatgen asseguts."},{"ref":"MAN.SVVH.000, § dimensions","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"Dimensions i pesos Les dimensions d’un autobús o autocar poden variar segons la configuració, però la normativa estableix uns límits generals: una alçada màxima de 4 metres, una amplada de fins a 2,55 metres (2,60 m en casos especials) i una longitud que oscil·la entre 13,5 i 18,75 metres, segons el nombre d’eixos o si és articulat."}]},{"text":"El camió articulat té dues parts diferenciades: el cap tractor, on hi ha el motor i la cabina, i el semiremolc, que és la unitat de càrrega.","refs":[{"ref":"MAN.SVVH.000, § camió articulat","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"Consta de dues parts diferenciades: el cap tractor (on hi ha el motor i la cabina) i el semiremolc, que és la unitat de càrrega."}]}]},{"n":"6","title":"Incidents ferroviaris","blocks":[{"text":"Els trens d''alta velocitat, com el TAV (AVE a Espanya), poden superar els 300 km/h i circulen per infraestructures específiques. Pel seu gran pes i inèrcia, la distància de frenada d''un tren és molt superior a la d''un vehicle de carretera.","refs":[{"ref":"MAN.SVVH.000, § alta velocitat","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"Trens d’alta velocitat: com el TAV (AVE a Espanya), que poden assolir més de 300 km/h i operen en infraestructures específiques."},{"ref":"MAN.SVVH.000, § frenada","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"Sistemes de frenada i inèrcia Una característica fonamental dels trens és la seva gran massa i inèrcia, que fan que la distància de frenada sigui molt superior a la d’un vehicle de carretera."}]},{"text":"Abans de començar qualsevol intervenció a la via cal coordinar-se amb el centre de control ferroviari, que és l''únic que pot garantir que no hi circulin altres trens per aquella línia. Encara que el comboi sembli aturat i la zona sembli segura, cal confirmació oficial que s''ha tallat la circulació i que la tracció elèctrica està desconnectada. Les zones reforçades dels trens poden ser molt difícils de tallar amb eines convencionals com les cisalles hidràuliques, i sovint cal buscar punts més febles o utilitzar serres de tall tèrmic o discos d''abrasió.","refs":[{"ref":"MAN.SVVH.000, § centre de control","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"Comunicació amb el centre de control ferroviari Un aspecte fonamental abans de començar qualsevol intervenció a la via és la coordinació amb el centre de control ferroviari, que és l’únic que pot garantir que no hi circulin altres trens per aquella línia."},{"ref":"MAN.SVVH.000, § tracció elèctrica","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"Encara que el comboi sinistrat sembli aturat i la zona aparentment segura, cal obtenir confirmació oficial que la circulació ha estat tallada i que el sistema de tracció elèctrica està desconnectat."},{"ref":"MAN.SVVH.000, § tall","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"Aquestes zones poden ser molt difícils de tallar amb eines convencionals com les cisalles hidràuliques, i sovint obliguen a buscar punts més febles o utilitzar equips especialitzats com serres de tall tèrmic o discos d’abrasió."}]}]},{"n":"7","title":"Valoració inicial de l''escenari i biomecànica de l''accident","blocks":[{"text":"La valoració és la fase prèvia i inicial de tota intervenció en accidents de mobilitat. Una eina de la valoració és la biomecànica de l''accident de trànsit, la ciència que, a partir de la física i de la medicina, estudia els mecanismes lesius d''un accident.","refs":[{"ref":"MAN.SVVH.000, § valoració","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"Valoració La valoració és la fase prèvia i inicial de qualsevol intervenció en accidents de mobilitat."},{"ref":"MAN.SVVH.000, § biomecànica","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"Biomecànica de l’accident de trànsit La biomecànica de l’accident de trànsit és la ciència que, basant-se en la física i la medicina, estudia els mecanismes lesius d’un accident."}]},{"text":"L''energia cinètica prèvia al xoc és Ec = ½ m × V². La massa compta, però el factor més determinant és la velocitat, perquè a la fórmula s''eleva al quadrat. Un dels criteris que indiquen un impacte d''alta energia és que el vehicle s''hagi desplaçat més de 7 metres del lloc de l''impacte. Els tipus d''impacte i les posicions finals dels vehicles no es detallen als extractes revisats; cal consultar el manual.","refs":[{"ref":"MAN.SVVH.000, § energia cinètica","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"Ec = ½ m x V2 Si bé la massa (m) és important, és fàcil deduir que el factor més determinant a l’hora de concretar la quantitat d’energia cinètica prèvia al xoc és la velocitat (V), ja que en la fórmula s’eleva al quadrat."},{"ref":"MAN.SVVH.000, § alta energia","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"Desplaçament del vehicle a més de 7 metres del lloc de l’impacte"}]}]},{"n":"8","title":"Tipus d''atrapament","blocks":[{"text":"Hi ha dos grans tipus d''atrapament. Quan la víctima no està enganxada entre la ferralla però no pot sortir pel seu estat, es diu que està atrapada per les seves pròpies lesions; en tots els casos, les necessitats immediates i el benestar de les víctimes són la primera prioritat. Quan les víctimes estan enganxades entre la ferralla hi ha atrapament estructural, i cal desplaçar elements del vehicle per alliberar-les.","refs":[{"ref":"MAN.SVVH.000, § atrapament per lesions","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"En aquest tipus de situació s’acostuma a dir que la víctima està atrapada per les seves pròpies lesions, i cal tenir molt present que les necessitats immediates i el benestar de les víctimes són la nostra primera prioritat a l’hora de treballar en accidents."},{"ref":"MAN.SVVH.000, § atrapament estructural","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"En aquest cas sí que hi ha atrapament estructural, és a dir, les víctimes estan enganxades entre la ferralla, per la qual cosa es fa imprescindible desplaçar elements del vehicle per tal d’alliberar-les."}]}]},{"n":"9","title":"Pla d''acció: extracció planificada, pla B i alliberament immediat","blocks":[{"text":"El pla A (extracció planificada) és l''opció prioritària quan l''estat de la víctima és estable i hi ha temps i condicions per fer una extracció tècnicament segura i respectuosa amb la seva situació clínica. El pla B es prepara en paral·lel al pla A i s''activa si la víctima s''agreuja sobtadament o si sorgeix una situació que obliga a reduir el temps d''extracció.","refs":[{"ref":"MAN.SVVH.000, § pla A","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"És l’opció prioritària quan l’estat de la víctima és estable i es disposa de temps i condicions per fer una extracció tècnicament segura i respectuosa amb la seva situació clínica."},{"ref":"MAN.SVVH.000, § pla B","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"És l’opció prevista en paral·lel al Pla A, i es posa en marxa en cas que es produeixi un agreujament sobtat de l’estat de la víctima o una situació sobrevinguda que obligui a reduir el temps d’extracció de la persona afectada."}]},{"text":"L''alliberament immediat és el cas extrem: només s''aplica en una aturada cardíaca presenciada o en un incendi que no es pot controlar de manera immediata. En aquests casos, si és possible, se sol fer servir la maniobra de Rautek.","refs":[{"ref":"MAN.SVVH.000, § alliberament immediat","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"Seria el cas extrem d’alliberament immediat i s’aplicaria només en cas d’aturada cardíaca presenciada o d’incendi no controlable de forma immediata."},{"ref":"MAN.SVVH.000, § Rautek","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"En aquests casos, si és possible, s’acostuma a optar per la maniobra de Rautek."}]}]},{"n":"10","title":"Maniobres bàsiques i principis de seguretat","blocks":[{"text":"L''estabilització parteix del control dels moviments del vehicle (desplaçament longitudinal, balanceig i capcineig) i l''excarceració, de desplaçar elements del vehicle quan hi ha atrapament estructural. El detall de l''abordatge, la gestió de vidres, les obertures i els desmuntatges, i les mesures preventives específiques no és als extractes revisats; cal consultar el manual MAN.SVVH.000. Com a principi de seguretat, als accidents ferroviaris no s''actua a la via sense confirmació oficial del tall de circulació i de la desconnexió de la tracció elèctrica.","refs":[{"ref":"MAN.SVVH.000, § atrapament estructural","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"es fa imprescindible desplaçar elements del vehicle per tal d’alliberar-les."},{"ref":"MAN.SVVH.000, § tracció elèctrica","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"cal obtenir confirmació oficial que la circulació ha estat tallada i que el sistema de tracció elèctrica està desconnectat."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"2019: any amb més accidentalitat (més de 24.000 accidents amb víctimes); 2023: 23.591.","refs":[{"ref":"MAN.SVVH.000, § accidentalitat","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"L’any amb més accidentalitat va ser el 2019, superant els 24.000 accidents amb víctimes"}]},{"text":"Balanceig = pivota a dreta i esquerra; capcineig = pivota endavant i endarrere; longitudinal = endavant i endarrere en el sentit de la marxa.","refs":[{"ref":"MAN.SVVH.000, § capcineig","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"Capcineig És un moviment pivotant endavant i endarrere sense desplaçament longitudinal."}]},{"text":"Bastidor = esquelet inferior (motor, suspensió, transmissió); superestructura = habitacle. Autocars: passatgers sempre asseguts. Alçada màxima: 4 m.","refs":[{"ref":"MAN.SVVH.000, § dimensions","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"una alçada màxima de 4 metres"}]},{"text":"Camió articulat = cap tractor + semiremolc. Seguretat terciària = actua després de l''accident.","refs":[{"ref":"MAN.SVVH.000, § camió articulat","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"Consta de dues parts diferenciades: el cap tractor (on hi ha el motor i la cabina) i el semiremolc, que és la unitat de càrrega."}]},{"text":"Tren: només el centre de control ferroviari garanteix que no circulen altres trens; TAV > 300 km/h; frenada llarga per massa i inèrcia.","refs":[{"ref":"MAN.SVVH.000, § centre de control","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"que és l’únic que pot garantir que no hi circulin altres trens per aquella línia."}]},{"text":"Ec = ½ m × V²: la velocitat és el factor més determinant. Alta energia: desplaçament de més de 7 m.","refs":[{"ref":"MAN.SVVH.000, § energia cinètica","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"el factor més determinant a l’hora de concretar la quantitat d’energia cinètica prèvia al xoc és la velocitat (V), ja que en la fórmula s’eleva al quadrat."}]},{"text":"Pla A: víctima estable. Pla B: en paral·lel, si s''agreuja. Alliberament immediat: només aturada cardíaca presenciada o incendi no controlable; maniobra de Rautek.","refs":[{"ref":"MAN.SVVH.000, § alliberament immediat","law":"MAN.SVVH.000","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf","quote":"s’aplicaria només en cas d’aturada cardíaca presenciada o d’incendi no controlable de forma immediata."}]}]}]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf', null, null, null, null
