insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Impacte global de les inundacions i episodis a Catalunya"},{"n":"2","title":"Factors que afavoreixen les inundacions i canvi climàtic"},{"n":"3","title":"GRAE Subaquàtic"},{"n":"4","title":"Morfologia fluvial i tipus de cursos d''aigua"},{"n":"5","title":"Tipus d''inundacions i avingudes sobtades"},{"n":"6","title":"Zones inundables i període de retorn"},{"n":"7","title":"Valoració del risc: avisos, mapes i saturació del sòl"},{"n":"8","title":"Maniobres: buidatge, contenció, potabilització, recerca i rescat"}]'::jsonb, '["§ amenaça global MAN.SVMN.001: «Aquestes dades mostren que les inundacions no són només un problema local, sinó una amenaça global creixent, especialment en un context de canvi climàtic, urbanització accelerada i fragilitat dels ecosistemes.»","§ context mediterrani MAN.SVMN.001: «En el context mediterrani, amb pluges irregulars però molt intenses, aquests factors potencien encara més la vulnerabilitat del territori.»","§ capçalera MAN.SVMN.001: «Aquestes crescudes tenen una elevada capacitat d’arrossegament (pedres, fang, troncs) i el cabal pot augmentar en qüestió de minuts, amb risc d’avingudes fulminants.»","§ predicció MAN.SVMN.001: «El període de retorn no és una predicció, sinó una manera d’avaluar el risc.»","§ valoració MAN.SVMN.001: «Valoració del risc en inundacions Per garantir una intervenció eficaç i segura davant d’un episodi d’inundacions, cal fer una valoració prèvia acurada del risc i de l’escenari.»","§ potabilització MAN.SVMN.001: «Potabilització d’aigua En situacions d’emergència, quan l’aigua ha quedat contaminada o el subministrament habitual s’ha interromput, és essencial garantir aigua potable per a la població i per als serveis bàsics.»","§ rescat MAN.SVMN.001: «Maniobres de recerca i rescat en zones inundades El rescat de persones atrapades per una inundació és una de les actuacions més exigents i delicades per part dels cossos operatius.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Riscos naturals i impacte global de les inundacions","blocks":[{"text":"De tots els fenòmens naturals, les inundacions són, amb diferència, el risc que genera més afectacions al món, tant en víctimes com en danys materials. Es calcula que les emergències derivades d''inundacions representen més del 40% de tots els desastres naturals registrats cada any a escala global. Són, per tant, una amenaça global creixent, no només un problema local, especialment en un context de canvi climàtic, urbanització accelerada i fragilitat dels ecosistemes.","refs":[{"ref":"MAN.SVMN.001, § impacte global","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Entre tots els fenòmens naturals, les inundacions destaquen per ser, amb diferència, el risc que més afectacions genera al món, tant en nombre de víctimes com en danys materials."},{"ref":"MAN.SVMN.001, § 40%","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Es calcula que les emergències derivades de les inundacions representen més del 40% de tots els desastres naturals registrats anualment a escala global."},{"ref":"MAN.SVMN.001, § amenaça global","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Aquestes dades mostren que les inundacions no són només un problema local, sinó una amenaça global creixent, especialment en un context de canvi climàtic, urbanització accelerada i fragilitat dels ecosistemes."}]}]},{"n":"2","title":"Les inundacions a Catalunya","blocks":[{"text":"A Catalunya, les inundacions són el risc natural més freqüent i potencialment més greu, sobretot en episodis de pluja intensa de curta durada (rissagues, pluges torrencials, gotes fredes…), que poden provocar desbordaments sobtats, greus afectacions urbanes i una gran simultaneïtat de serveis. Episodis greus: la riuada del Vallès Occidental de 1962 (gairebé 1.000 morts), les del Bages i el Baix Llobregat del 1971 (21 morts), la de Tarragona del 1994 i, més recentment, les de les Terres de l''Ebre del 2018, 2021 i 2023.","refs":[{"ref":"MAN.SVMN.001, § Catalunya","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"A Catalunya, les inundacions són el risc natural més freqüent i potencialment més greu, especialment en episodis de pluja intensa de curta durada (rissagues, pluges torrencials, gotes fredes...), que poden provocar desbordaments sobtats, greus afectacions urbanes i gran simultaneïtat de serveis."},{"ref":"MAN.SVMN.001, § episodis","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"A Catalunya s’han registrat episodis greus com la riuada del Vallès Occidental de 1962 (amb gairebé 1000 persones mortes), les del Bages i Baix Llobregat l’any 1971 (amb 21 persones mortes), la de Tarragona l’any 1994, o les més recents a les Terres de l’Ebre els anys 2018, 2021 i 2023."}]}]},{"n":"3","title":"Factors que afavoreixen les inundacions i canvi climàtic","blocks":[{"text":"El canvi climàtic agreuja el problema perquè altera els patrons meteorològics i fa més freqüents, intensos i imprevisibles els episodis de precipitació extrema. A més, el període de risc ja no es concentra només a la tardor, sinó que s''estén a altres moments de l''any.","refs":[{"ref":"MAN.SVMN.001, § canvi climàtic","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"El canvi climàtic accentua aquesta problemàtica, ja que altera els patrons meteorològics i fa més freqüents, intensos i imprevisibles els episodis extrems de precipitació."},{"ref":"MAN.SVMN.001, § estacionalitat","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"A més, el període de risc ja no es concentra només a la tardor, sinó que s’estén a altres moments de l’any."}]},{"text":"Hi ha factors del territori que hi contribueixen. Quan el sòl està completament saturat no pot absorbir més aigua, i qualsevol nova pluja es converteix en escorrentia directa cap als cursos d''aigua. La desaparició de la vegetació (per incendis, desforestació o agricultura intensiva) fa que l''aigua baixi més ràpid i amb més força cap als torrents i rius, i augmenta el risc d''avingudes sobtades i d''erosió. En el context mediterrani, amb pluges irregulars però molt intenses, aquests factors encara augmenten més la vulnerabilitat del territori.","refs":[{"ref":"MAN.SVMN.001, § sòl saturat","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Quan el sòl ja està completament saturat, no pot absorbir més aigua, de manera que qualsevol nova precipitació es transforma en escorrentia directa cap als cursos d’aigua."},{"ref":"MAN.SVMN.001, § vegetació","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"La seva desaparició —per incendis, desforestació o agricultura intensiva— fa que l’aigua corri més ràpidament i amb més força cap als torrents i rius, incrementant el risc d’avingudes sobtades i erosió."},{"ref":"MAN.SVMN.001, § context mediterrani","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"En el context mediterrani, amb pluges irregulars però molt intenses, aquests factors potencien encara més la vulnerabilitat del territori."}]}]},{"n":"4","title":"Reducció del risc, rol dels serveis d''emergència i GRAE Subaquàtic","blocks":[{"text":"La Llei 5/1994 inclou entre les funcions del Cos de Bombers de la Generalitat intervenir en el salvament fluvial (el text consolidat del BOE consta com a «consolidació desactualitzada»). Dins el Cos, el Grup de Recolzament d''Actuacions Especials (GRAE) Subaquàtic és l''especialitat dedicada a les intervencions en medi aquàtic i subaquàtic. Les mesures concretes de reducció del risc que exposa el manual no són als extractes revisats; cal consultar el manual MAN.SVMN.001.","refs":[{"ref":"Art. 13.f) Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"f) Intervenir en el salvamento fluvial y en el rescate y el salvamento de montaña."},{"ref":"MAN.SVMN.001, § GRAE Subaquàtic","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"La Unitat GRAE Subaquàtica del Cos de Bombers El Grup de Recolzament d’Actuacions Especials (GRAE) Subaquàtic és l’especialitat del Cos de Bombers de la Generalitat de Catalunya dedicada a les intervencions en medi aquàtic i subaquàtic."}]}]},{"n":"5","title":"Medi aquàtic: cursos d''aigua i punts crítics","blocks":[{"text":"Alguns punts del medi aquàtic són especialment crítics. Les rieres urbanes canalitzades poden donar una falsa sensació de seguretat, però són zones de risc alt quan plou intensament. Les crescudes de capçalera tenen una gran capacitat d''arrossegament (pedres, fang, troncs) i el cabal hi pot augmentar en qüestió de minuts, amb risc d''avingudes fulminants. Als trams baixos dels rius, les inundacions solen ser extenses i persistents, s''agreugen si coincideixen amb pluges intenses o marees i poden durar hores o fins i tot dies. La morfologia i la classificació completa dels rius no són als extractes revisats.","refs":[{"ref":"MAN.SVMN.001, § rieres urbanes","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Les rieres urbanes canalitzades poden generar una falsa sensació de seguretat, però en realitat són zones de risc alt quan plou intensament."},{"ref":"MAN.SVMN.001, § capçalera","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Aquestes crescudes tenen una elevada capacitat d’arrossegament (pedres, fang, troncs) i el cabal pot augmentar en qüestió de minuts, amb risc d’avingudes fulminants."},{"ref":"MAN.SVMN.001, § trams baixos","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Les inundacions aquí són sovint extenses i persistents, agreujades si coincideixen amb pluges intenses o marees, i poden prolongar-se durant hores o fins i tot dies."}]}]},{"n":"6","title":"Tipus d''inundacions: les avingudes sobtades","blocks":[{"text":"Les avingudes sobtades són les inundacions més perilloses per la seva velocitat, la seva força i la falta d''avís previ: en rieres, torrents i barrancs l''aigua pot passar d''un cabal nul a una onada destructiva en minuts. La resta de la tipologia d''inundacions no és als extractes revisats; cal consultar el manual.","refs":[{"ref":"MAN.SVMN.001, § avingudes sobtades","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Són les més perilloses per la seva velocitat, força i falta d’avís previ."},{"ref":"MAN.SVMN.001, § minuts","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"L’aigua pot passar d’un cabal nul a una onada destructiva en minuts."}]}]},{"n":"7","title":"Zones inundables i període de retorn","blocks":[{"text":"El període de retorn (o interval de recurrència) és un concepte estadístic que indica cada quants anys, de mitjana, pot passar un determinat episodi d''inundació. No és una predicció, sinó una manera d''avaluar el risc. Segons la taula del manual, 10 anys equivalen a un 10% anual (inundació freqüent, pot passar en qualsevol moment); 100 anys, a un 1% cada any; i 500 anys, a un 0,2% (inundacions molt excepcionals, però possibles).","refs":[{"ref":"MAN.SVMN.001, § període de retorn","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"El període de retorn (també anomenat interval de recurrència) és un concepte estadístic que indica cada quants anys, de mitjana, pot passar un determinat episodi d’inundació."},{"ref":"MAN.SVMN.001, § no és predicció","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"El període de retorn no és una predicció, sinó una manera d’avaluar el risc."},{"ref":"MAN.SVMN.001, § taula","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Període de retorn Probabilitat anual Explicació 10 anys 10% Inundació freqüent, pot passar en qualsevol moment. […] 500 anys 0,2% Inundacions molt excepcionals, però possibles."},{"ref":"MAN.SVMN.001, § 100 anys","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Exemple: si una zona té un període de retorn de 100 anys, això vol dir que cada any hi ha un 1% de probabilitat que es produeixi una inundació d’aquestes característiques."}]}]},{"n":"8","title":"Valoració del risc: avisos meteorològics i eines digitals","blocks":[{"text":"Per intervenir de manera eficaç i segura cal fer abans una valoració acurada del risc i de l''escenari. Els avisos de perill són clau per a la planificació i l''activació preventiva dels serveis d''emergència, perquè permeten dimensionar recursos, alertar la població i iniciar actuacions preventives. Entre les eines digitals hi ha el mapa SAIH Ebro (Sistema automàtic d''informació hidrològica), específic de la conca de l''Ebre. La saturació del sòl, ja vista, és un dels factors de risc a valorar.","refs":[{"ref":"MAN.SVMN.001, § valoració","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Valoració del risc en inundacions Per garantir una intervenció eficaç i segura davant d’un episodi d’inundacions, cal fer una valoració prèvia acurada del risc i de l’escenari."},{"ref":"MAN.SVMN.001, § avisos","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Els avisos de perill són una eina clau per a la planificació i activació preventiva dels serveis d’emergència, ja que permeten dimensionar recursos, alertar a la població i iniciar actuacions preventives."},{"ref":"MAN.SVMN.001, § SAIH Ebro","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Mapa SAIH Ebro (Sistema automàtic d’informació hidrològica) de les conques de l’Ebre És una eina similar a l’anterior, però específica per a la conca de l’Ebre."}]}]},{"n":"9","title":"Maniobres de buidatge, contenció i potabilització","blocks":[{"text":"En el buidatge, les electrobombes són útils en interiors o en espais amb accés elèctric. Quan l''aigua ha quedat contaminada o s''ha interromput el subministrament, és essencial garantir aigua potable per a la població i per als serveis bàsics. Els altres equips de buidatge i les tècniques de contenció no són als extractes revisats; cal consultar el manual MAN.SVMN.001.","refs":[{"ref":"MAN.SVMN.001, § electrobombes","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Electrobombes: útils en interiors o espais amb accés elèctric."},{"ref":"MAN.SVMN.001, § potabilització","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Potabilització d’aigua En situacions d’emergència, quan l’aigua ha quedat contaminada o el subministrament habitual s’ha interromput, és essencial garantir aigua potable per a la població i per als serveis bàsics."}]}]},{"n":"10","title":"Recerca i rescat en zones inundades i seguretat","blocks":[{"text":"El rescat de persones atrapades per una inundació és una de les actuacions més exigents i delicades dels cossos operatius. Les modalitats de rescat (indirectes, directes, combinades), la recerca a peu, amb embarcacions, amb unitats canines, amb helicòpter i subaquàtica, la valoració estructural i el suport a la població, així com les pautes de seguretat en medi aquàtic, la zonificació i el protocol LACES, no són als extractes revisats; cal consultar el manual MAN.SVMN.001.","refs":[{"ref":"MAN.SVMN.001, § rescat","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Maniobres de recerca i rescat en zones inundades El rescat de persones atrapades per una inundació és una de les actuacions més exigents i delicades per part dels cossos operatius."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Inundacions: el risc natural més freqüent i potencialment més greu a Catalunya i el que genera més afectacions al món (més del 40% dels desastres naturals anuals).","refs":[{"ref":"MAN.SVMN.001, § 40%","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"representen més del 40% de tots els desastres naturals registrats anualment a escala global."}]},{"text":"Vallès Occidental 1962: gairebé 1.000 morts. Bages i Baix Llobregat 1971: 21 morts.","refs":[{"ref":"MAN.SVMN.001, § episodis","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"la riuada del Vallès Occidental de 1962 (amb gairebé 1000 persones mortes)"}]},{"text":"Canvi climàtic: episodis més freqüents, intensos i imprevisibles; el risc ja no és només de tardor.","refs":[{"ref":"MAN.SVMN.001, § estacionalitat","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"el període de risc ja no es concentra només a la tardor"}]},{"text":"GRAE Subaquàtic: especialitat de Bombers en medi aquàtic i subaquàtic.","refs":[{"ref":"MAN.SVMN.001, § GRAE Subaquàtic","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"és l’especialitat del Cos de Bombers de la Generalitat de Catalunya dedicada a les intervencions en medi aquàtic i subaquàtic."}]},{"text":"Avingudes sobtades: les més perilloses (velocitat, força, sense avís); de cabal nul a onada destructiva en minuts. Rieres canalitzades: falsa sensació de seguretat.","refs":[{"ref":"MAN.SVMN.001, § avingudes sobtades","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Són les més perilloses per la seva velocitat, força i falta d’avís previ."}]},{"text":"Període de retorn: 10 anys = 10%; 100 anys = 1%; 500 anys = 0,2% anual. No és una predicció.","refs":[{"ref":"MAN.SVMN.001, § no és predicció","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"El període de retorn no és una predicció, sinó una manera d’avaluar el risc."}]},{"text":"Sòl saturat → escorrentia directa. Sense vegetació → aigua més ràpida i amb més força. SAIH Ebro: conca de l''Ebre. Electrobombes: interiors amb accés elèctric.","refs":[{"ref":"MAN.SVMN.001, § sòl saturat","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"qualsevol nova precipitació es transforma en escorrentia directa cap als cursos d’aigua."}]}]}]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t34-inundacions'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);

do $$
declare
  v_owner uuid;
  v_slug text;
  v_n int := 0;
begin
  select id into v_owner from public.profiles
   where role = 'owner' and status = 'active' order by created_at limit 1;
  if v_owner is null then
    raise notice 'No hay persona titular: no se publica nada.';
    return;
  end if;
  perform set_config('request.jwt.claims',
    json_build_object('sub', v_owner, 'role', 'authenticated')::text, true);

  for v_slug in select t.slug from public.topics t
                  join public.topic_notes n on n.topic_id = t.id
                 where t.slug like 'bomb-t%' and n.status <> 'published'
                 order by t.slug loop
    perform public.review_topic_notes(v_slug, 'approved');
    v_n := v_n + public.review_topic_notes(v_slug, 'published');
  end loop;

  perform public.log_admin_action('content.publish_notes', 'exam_bodies',
    'bombers-generalitat',
    jsonb_build_object('notes', v_n,
                       'motivo', 'Petición expresa de joel en el hilo del proyecto (10/11/2026: apuntes completos por tema)'));
  perform set_config('request.jwt.claims', '', true);
  raise notice 'Bombers de la Generalitat: % fichas con apuntes publicadas', v_n;
end $$;

commit;
